const rupee = (n) => "₹" + n.toLocaleString("en-IN");
const cr = (n) => {
  if (n >= 1e7) { const x = n / 1e7; return "₹" + (Number.isInteger(x) ? x : x.toFixed(2).replace(/\.?0+$/, "")) + " Cr"; }
  if (n >= 1e5) { const x = n / 1e5; return "₹" + (Number.isInteger(x) ? x : x.toFixed(1).replace(/\.0$/, "")) + " L"; }
  return "₹" + n.toLocaleString("en-IN");
};

/* deterministic QR-style matrix from a string — same value always draws the same code */
function QR({ value = "MB", size = 112 }) {
  const n = 21, pad = 1, tot = n + pad * 2, cell = size / tot;
  let h = 2166136261; for (let i = 0; i < value.length; i++) { h ^= value.charCodeAt(i); h = Math.imul(h, 16777619); }
  const rnd = () => { h ^= h << 13; h ^= h >>> 17; h ^= h << 5; h >>>= 0; return h / 4294967296; };
  const finder = (x, y) => (x < 7 && y < 7) || (x > n - 8 && y < 7) || (x < 7 && y > n - 8);
  const cells = [];
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) { if (finder(x, y)) continue; if (rnd() > 0.52) cells.push([x, y]); }
  const eye = (ox, oy) => [[ox, oy, 7, 7, "#16345F"], [ox + 1, oy + 1, 5, 5, "#fff"], [ox + 2, oy + 2, 3, 3, "#16345F"]];
  const eyes = [...eye(0, 0), ...eye(n - 7, 0), ...eye(0, n - 7)];
  return (
    <svg width={size} height={size} style={{ background: "#fff", borderRadius: 8, display: "block" }} shapeRendering="crispEdges">
      {eyes.map(([x, y, w, hh, c], i) => <rect key={"e" + i} x={(x + pad) * cell} y={(y + pad) * cell} width={w * cell} height={hh * cell} fill={c} />)}
      {cells.map(([x, y], i) => <rect key={i} x={(x + pad) * cell} y={(y + pad) * cell} width={cell} height={cell} fill="#16345F" />)}
    </svg>
  );
}

/* software picks the right vehicle for the load — from a hand cart to a multi-axle trailer */
const VEHICLES = {
  cart:    { id: "cart",    name: "Hand cart (rehri)",       cap: "up to ~150 kg" },
  auto:    { id: "auto",    name: "Auto / tempo",            cap: "up to ~500 kg" },
  pickup:  { id: "pickup",  name: "Mahindra pickup",         cap: "up to ~1.5 T" },
  truck6:  { id: "truck6",  name: "6-wheeler truck",         cap: "9–16 T" },
  truck10: { id: "truck10", name: "10-wheeler truck",        cap: "16–25 T" },
  trailer: { id: "trailer", name: "Multi-axle trailer",      cap: "25–40 T" },
};
const VLADDER = ["cart", "auto", "pickup", "truck6", "truck10", "trailer"];
function estimateTruck(item) {
  const s = (item || "").toLowerCase();
  const num = (m) => m ? parseFloat(m[1].replace(/,/g, "")) : 0;
  const t = num(s.match(/(\d[\d,\.]*)\s*(?:t|ton|tonne|mt)\b/));
  const v = num(s.match(/(\d[\d,\.]*)\s*(?:m³|m3|cum|cubic)/));
  const b = num(s.match(/(\d[\d,\.]*)\s*bags?/));
  const nos = num(s.match(/(\d[\d,\.]*)\s*(?:nos|no\.?|pcs|pieces|units)\b/));
  if (t >= 40 || v >= 200) return VEHICLES.trailer;
  if (t >= 16 || v >= 60 || b >= 2000) return VEHICLES.truck10;
  if (t >= 6 || v >= 18 || b >= 400) return VEHICLES.truck6;
  if (t >= 1 || v >= 4 || b >= 80 || nos >= 1000) return VEHICLES.pickup;
  if (t > 0 || v > 0 || b > 0 || nos >= 50) return VEHICLES.auto;
  return VEHICLES.cart;
}
function VehicleFigure({ type, w = 72 }) {
  const h = w * 0.6, nav = "#224A85", cab = "#C7A162", steel = "#EAF0F8";
  const W = (cx, cy, r) => <g key={cx + "-" + cy}><circle cx={cx} cy={cy} r={r} fill="#16345F" /><circle cx={cx} cy={cy} r={r * 0.42} fill="#fff" /></g>;
  const wrap = (kids) => <svg width={w} height={h} viewBox="0 0 72 44" style={{ display: "block" }}>{kids}</svg>;
  switch (type) {
    case "cart": return wrap(<>
      <rect x="8" y="21" width="42" height="6" rx="2" fill={nav} />
      <rect x="13" y="9" width="30" height="13" rx="2" fill={cab} />
      <line x1="50" y1="24" x2="63" y2="15" stroke={nav} strokeWidth="2.5" strokeLinecap="round" />
      {W(25, 33, 7)}
    </>);
    case "auto": return wrap(<>
      <path d="M16 31 Q14 11 30 11 L45 11 Q51 11 51 22 L51 31 Z" fill={nav} />
      <rect x="30" y="15" width="15" height="8" fill={cab} />
      {W(23, 34, 6)}{W(45, 34, 6)}
    </>);
    case "pickup": return wrap(<>
      <rect x="6" y="18" width="28" height="11" fill={nav} />
      <path d="M34 29 L34 13 L47 13 L53 22 L53 29 Z" fill={cab} />
      <rect x="46" y="16" width="5" height="5" fill={steel} />
      {W(17, 31, 6)}{W(47, 31, 6)}
    </>);
    case "truck6": return wrap(<>
      <rect x="5" y="11" width="35" height="18" fill={nav} />
      <path d="M40 29 L40 15 L51 15 L57 24 L57 29 Z" fill={cab} />
      <rect x="51" y="18" width="5" height="5" fill={steel} />
      {W(16, 33, 6)}{W(49, 33, 6)}
    </>);
    case "truck10": return wrap(<>
      <rect x="3" y="9" width="41" height="20" fill={nav} />
      <path d="M44 29 L44 14 L55 14 L61 24 L61 29 Z" fill={cab} />
      <rect x="55" y="17" width="5" height="5" fill={steel} />
      {W(13, 33, 5)}{W(25, 33, 5)}{W(53, 33, 5)}
    </>);
    case "trailer": return wrap(<>
      <rect x="2" y="12" width="45" height="3" fill="#A0803C" />
      <rect x="2" y="15" width="45" height="11" fill={nav} />
      <path d="M47 26 L47 13 L57 13 L63 24 L63 26 Z" fill={cab} />
      <rect x="57" y="16" width="5" height="5" fill={steel} />
      {W(10, 30, 5)}{W(21, 30, 5)}{W(33, 30, 5)}{W(55, 30, 5)}
    </>);
    default: return null;
  }
}

function useIsMobile(bp = 760) {  const [m, setM] = useState(typeof window !== "undefined" ? window.innerWidth < bp : false);
  useEffect(() => { const f = () => setM(window.innerWidth < bp); window.addEventListener("resize", f); f(); return () => window.removeEventListener("resize", f); }, [bp]);
  return m;
}

