function Card({ children, pad = 20, style }) {
  return <div style={{ background: C.panel, border: `1px solid ${C.line}`, borderRadius: 14, boxShadow: "0 1px 2px rgba(34,64,106,.04), 0 10px 28px rgba(34,64,106,.05)", padding: pad, ...style }}>{children}</div>;
}
function Eyebrow({ children, color = C.gold }) {
  return <div style={{ font: `600 11px/1.4 ${sans}`, letterSpacing: "0.16em", textTransform: "uppercase", color }}>{children}</div>;
}
function Pill({ children, tone = "gold" }) {
  const map = { gold: [C.goldSoft, C.goldDeep], green: [C.greenSoft, C.green], red: [C.redSoft, C.red], amber: [C.amberSoft, C.amber], stone: [C.lineSoft, C.stone] }[tone];
  return <span style={{ background: map[0], color: map[1], font: `600 11px/1 ${sans}`, padding: "5px 9px", borderRadius: 6, whiteSpace: "nowrap" }}>{children}</span>;
}
function GoldButton({ children, onClick, ghost, small }) {
  return <button onClick={onClick} style={{ cursor: "pointer", border: ghost ? `1px solid ${C.gold}` : "none", background: ghost ? "transparent" : `linear-gradient(180deg, #2A4C7C, ${C.ink})`, color: ghost ? C.goldDeep : "#fff", font: `600 ${small ? 12 : 13}px ${sans}`, padding: small ? "8px 13px" : "11px 17px", borderRadius: 10, letterSpacing: "0.01em", boxShadow: ghost ? "none" : "0 2px 6px rgba(34,64,106,.18)" }}>{children}</button>;
}
function Gauge({ value = 82, size = 168 }) {
  const [v, setV] = useState(0);
  useEffect(() => { const t = setTimeout(() => setV(value), 150); return () => clearTimeout(t); }, [value]);
  const r = size / 2 - 14, cx = size / 2, cy = size / 2;
  const a0 = Math.PI * 0.82, a1 = Math.PI * 2.18, ang = a0 + (a1 - a0) * (v / 100);
  const pt = (a, rad) => [cx + rad * Math.cos(a), cy + rad * Math.sin(a)];
  const arc = (from, to, rad) => { const [x0, y0] = pt(from, rad), [x1, y1] = pt(to, rad); const large = to - from > Math.PI ? 1 : 0; return `M ${x0} ${y0} A ${rad} ${rad} 0 ${large} 1 ${x1} ${y1}`; };
  const tone = v >= 90 ? C.green : v >= 75 ? C.gold : C.red;
  return (
    <div style={{ position: "relative", width: size, height: size * 0.78 }}>
      <svg width={size} height={size} style={{ position: "absolute", top: 0, left: 0 }}>
        <path d={arc(a0, a1, r)} stroke={C.line} strokeWidth="10" fill="none" strokeLinecap="round" />
        <path d={arc(a0, ang, r)} stroke={tone} strokeWidth="10" fill="none" strokeLinecap="round" style={{ transition: "all 1s cubic-bezier(.2,.8,.2,1)" }} />
      </svg>
      <div style={{ position: "absolute", top: "34%", width: "100%", textAlign: "center" }}>
        <div style={{ font: `400 40px ${serif}`, color: C.ink }}>{Math.round(v)}<span style={{ font: `400 16px ${serif}`, color: C.stone }}>%</span></div>
        <div style={{ font: `600 10px ${sans}`, letterSpacing: "0.14em", textTransform: "uppercase", color: tone, marginTop: 2 }}>{v >= 90 ? "Immaculate" : v >= 75 ? "Nearly there" : "Needs cleanup"}</div>
      </div>
    </div>
  );
}
const inp = { width: "100%", boxSizing: "border-box", padding: "12px 14px", margin: "7px 0 16px", border: `1px solid ${C.line}`, borderRadius: 10, font: `14px ${sans}`, background: "#fff", outline: "none", color: C.ink };
const roleChip = { cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 6, border: `1px solid ${C.line}`, background: "#fff", color: C.inkSoft, font: `600 12px ${sans}`, padding: "8px 11px", borderRadius: 20 };
const lbl = { font: `600 11px ${sans}`, letterSpacing: "0.1em", textTransform: "uppercase", color: C.inkSoft };

