/* ===== ACCESS CONSOLE — only the Chairman sees this ===== */
const AREA_GROUPS = [
  ["Money", [["expenses", "Expenses"], ["sales", "Sales & dues"], ["masters", "Masters"], ["accounts", "Reconciliation"], ["tax", "Tax & RERA"], ["cost", "Budget"]]],
  ["Buying", [["overview", "Purchase desk"], ["intent", "Intent → PO"], ["invoices", "Invoices"], ["subs", "Submissions"]]],
  ["Site", [["store", "Store floor"], ["inventory", "Inventory"], ["maintenance", "Maintenance"], ["security", "Gate"]]],
  ["People", [["people", "People"], ["hr", "HR Desk"], ["incentives", "Incentives"], ["attendance", "Attendance"]]],
  ["Shared", [["calendar", "Calendar"], ["directory", "Directory"], ["firms", "Projects"], ["connect", "Connections"]]],
];
const POWERS = [["view", "See it"], ["edit", "Change it"], ["approve", "Approve it"], ["export", "Take it out"]];
const POWER_TONE = { view: "#3C78D8", edit: "#C7A162", approve: "#3E7C55", export: "#B0503C" };
const DEFAULT_GRANTS = () => {
  const g = {};
  Object.keys(USERS).forEach(r => {
    g[r] = {};
    AREA_GROUPS.forEach(([, areas]) => areas.forEach(([a]) => {
      const nav = (NAV[r] || []).map(n => n[0]);
      const on = r === "admin" || nav.includes(a);
      g[r][a] = { view: on, edit: on && r !== "admin" ? true : on, approve: r === "admin" || USERS[r].tier <= 2 ? on : false, export: r === "admin" ? true : false };
    }));
  });
  return g;
};

