/* ===== EXPORT — branded, right-sized, and never the same file twice ===== */
const PERIODS = [["current", "What is on screen"], ["m1", "This month"], ["m3", "Last 3 months"], ["fy", "This financial year"], ["all", "Everything on record"]];
const PERIOD_MULT = { current: 1, m1: 1.4, m3: 3.6, fy: 9, all: 22 };
function csvCell(v) { const s = String(v == null ? "" : v); return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s; }

function ExportPanel({ title, filterNote, cols, rows, trail, userKey, onClose, registry, onRegister }) {
  const mob = useIsMobile(); const { activeFirm } = useProc();
  const u = USERS[userKey] || USERS.purchase;
  const empId = ((typeof EMPLOYEES !== "undefined" ? EMPLOYEES : []).find(p => p.name === u.name) || {}).id || `MB-${(u.dept || "GEN").slice(0, 3).toUpperCase()}-0001`;
  const [fmt, setFmt] = useState("excel");
  const [period, setPeriod] = useState("current");
  const [withTrail, setWithTrail] = useState(false);
  const [withAttach, setWithAttach] = useState(false);
  const stamp = new Date();
  const stampStr = stamp.toLocaleString("en-IN", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" });
  const nRows = Math.round(rows.length * (PERIOD_MULT[period] || 1));
  const kb = Math.max(6, Math.round(nRows * (fmt === "pdf" ? 2.6 : 0.9) + (withTrail ? nRows * 3.1 : 0) + (withAttach ? nRows * 14 : 0)));
  const pages = Math.max(1, Math.ceil(nRows / 26) + (withTrail ? Math.ceil(nRows / 9) : 0));
  const heavy = kb > 900 || nRows > 400;
  const fileBase = `Marbella-${title.replace(/[^A-Za-z0-9]+/g, "-")}-${period}${withTrail ? "-trail" : ""}`;
  const dupe = (registry || []).find(r => r.key === fileBase + "-" + fmt);

  const head = [
    ["MARBELLA GROUP", ""],
    [activeFirm.firm, ""],
    [activeFirm.name + " · " + activeFirm.addr, ""],
    ["GSTIN " + activeFirm.gstin + " · RERA " + activeFirm.rera, ""],
    ["", ""],
    [title.toUpperCase(), ""],
    ["Filter applied", filterNote || "none"],
    ["Period", (PERIODS.find(p => p[0] === period) || [])[1]],
    ["Rows", String(nRows)],
    ["Generated", stampStr],
    ["Exported by", `${u.name} · ${u.role} · ${empId}`],
    ["", ""],
  ];
  const doExport = () => {
    if (fmt === "csv" || fmt === "excel") {
      const lines = [];
      head.forEach(h => lines.push(h.map(csvCell).join(",")));
      lines.push(cols.map(csvCell).join(","));
      rows.forEach(r => lines.push(r.map(csvCell).join(",")));
      if (withTrail && trail && trail.length) {
        lines.push(""); lines.push("DOCUMENT TRAIL");
        lines.push(["Record", "What happened", "Who", "When"].join(","));
        trail.forEach(t => lines.push(t.map(csvCell).join(",")));
      }
      lines.push(""); lines.push(csvCell("Marbella Group — internal. Do not forward outside the company."));
      downloadFile(`${fileBase}.${fmt === "csv" ? "csv" : "xls"}`, lines.join("\n"), fmt === "csv" ? "text/csv" : "application/vnd.ms-excel");
    } else {
      const esc = (x) => String(x == null ? "" : x).replace(/[&<>]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]));
      const doc = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${esc(title)}</title><style>
        @page{size:A4;margin:14mm}
        body{font:11px 'Helvetica Neue',Arial;color:#16345F;margin:0}
        .hd{border-bottom:2px solid #C7A162;padding-bottom:10px;margin-bottom:12px;display:flex;justify-content:space-between;gap:14px}
        .hd b{font:700 13px 'Helvetica Neue';letter-spacing:.14em}
        .hd .r{text-align:right;font-size:9.5px;color:#51617E;line-height:1.6}
        h1{font:400 20px Georgia,serif;margin:0 0 4px}
        .meta{font-size:10px;color:#51617E;margin-bottom:12px}
        table{width:100%;border-collapse:collapse}
        th{font-size:8.5px;letter-spacing:.07em;text-transform:uppercase;color:#8892A6;text-align:left;padding:0 6px 6px;border-bottom:1.5px solid #C7A162}
        td{font-size:10px;color:#3C4A63;padding:6px;border-bottom:1px solid #EEF2F8}
        h2{font:400 14px Georgia,serif;margin:18px 0 6px;color:#16345F}
        .ft{margin-top:16px;padding-top:8px;border-top:1px solid #E1E7F0;font-size:9px;color:#8892A6}
      </style></head><body>
      <div class="hd"><div><b>MARBELLA GROUP</b><div style="font-size:9px;color:#A0803C;letter-spacing:.2em">EMBRACE THE LUXE!</div></div>
      <div class="r">${esc(activeFirm.firm)}<br>${esc(activeFirm.name)} · ${esc(activeFirm.addr)}<br>GSTIN ${esc(activeFirm.gstin)} · RERA ${esc(activeFirm.rera)}</div></div>
      <h1>${esc(title)}</h1>
      <div class="meta">Filter: <b>${esc(filterNote || "none")}</b> · Period: ${esc((PERIODS.find(p => p[0] === period) || [])[1])} · ${nRows} rows<br>
      Generated ${esc(stampStr)} · Exported by ${esc(u.name)}, ${esc(u.role)} — ${esc(empId)}</div>
      <table><tr>${cols.map(c => `<th>${esc(c)}</th>`).join("")}</tr>
      ${rows.map(r => `<tr>${r.map(c => `<td>${esc(c)}</td>`).join("")}</tr>`).join("")}</table>
      ${withTrail && trail && trail.length ? `<h2>Document trail</h2><table><tr><th>Record</th><th>What happened</th><th>Who</th><th>When</th></tr>${trail.map(t => `<tr>${t.map(c => `<td>${esc(c)}</td>`).join("")}</tr>`).join("")}</table>` : ""}
      <div class="ft">Marbella Group — internal. Do not forward outside the company. ${esc(stampStr)} · ${esc(empId)}</div>
      <script>window.onload=()=>window.print()<\/script></body></html>`;
      const w = window.open("", "_blank");
      if (w) { w.document.write(doc); w.document.close(); }
      else downloadFile(`${fileBase}.html`, doc, "text/html");
    }
    onRegister && onRegister({ key: fileBase + "-" + fmt, title, filterNote, period, fmt, at: stampStr, by: u.name, rows: nRows, kb });
    toast(`${title} exported · ${nRows} rows`, "green");
    onClose();
  };

  return (
    <Overlay onClose={onClose} width={620}>
      <div style={{ padding: mob ? 18 : 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
          <Download size={17} color={C.gold} /><Eyebrow>Export</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>
        <h2 style={{ font: `400 20px ${serif}`, margin: "4px 0 4px" }}>{title}</h2>
        <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 14 }}>
          {filterNote ? <>You filtered by <b style={{ color: C.ink }}>{filterNote}</b> — {rows.length} rows on screen.</> : <>{rows.length} rows on screen.</>}
        </div>

        {dupe && (
          <div style={{ background: C.goldTint, border: `1px solid ${C.gold}`, borderRadius: 10, padding: 11, marginBottom: 12, display: "flex", gap: 9, font: `12px ${sans}`, color: C.inkSoft }}>
            <History size={15} color={C.goldDeep} style={{ flexShrink: 0 }} />
            <div><b style={{ color: C.inkDeep }}>You already made this file.</b> {dupe.by} exported the same thing on {dupe.at}. Share that one instead of creating another copy.</div>
          </div>
        )}

        <label style={{ ...lbl, fontSize: 9 }}>Format</label>
        <div style={{ display: "flex", gap: 7, margin: "6px 0 12px", flexWrap: "wrap" }}>
          {[["excel", "Excel"], ["csv", "CSV"], ["pdf", "PDF"]].map(([k, l]) => (
            <button key={k} onClick={() => setFmt(k)} style={{ cursor: "pointer", border: `1px solid ${fmt === k ? C.gold : C.line}`, background: fmt === k ? C.goldTint : "#fff", color: fmt === k ? C.goldDeep : C.stone, borderRadius: 20, padding: "7px 14px", font: `600 12px ${sans}` }}>{l}</button>
          ))}
        </div>

        <label style={{ ...lbl, fontSize: 9 }}>How far back</label>
        <select value={period} onChange={e => setPeriod(e.target.value)} style={{ ...sel, margin: "5px 0 12px" }}>
          {PERIODS.map(([k, l]) => <option key={k} value={k}>{l}</option>)}
        </select>

        <label style={{ ...lbl, fontSize: 9 }}>What to put in it</label>
        <div style={{ background: C.paper, border: `1px solid ${C.line}`, borderRadius: 11, padding: 12, marginTop: 6, marginBottom: 12 }}>
          <label style={{ display: "flex", alignItems: "flex-start", gap: 9, cursor: "pointer", marginBottom: 9 }}>
            <input type="checkbox" checked={withTrail} onChange={e => setWithTrail(e.target.checked)} style={{ marginTop: 3 }} />
            <span><b style={{ font: `600 12px ${sans}`, color: C.ink }}>The document trail</b><span style={{ display: "block", font: `11px ${sans}`, color: C.stone }}>Who did what and when behind every row — orders, deliveries, approvals, claims.</span></span>
          </label>
          <label style={{ display: "flex", alignItems: "flex-start", gap: 9, cursor: "pointer" }}>
            <input type="checkbox" checked={withAttach} onChange={e => setWithAttach(e.target.checked)} style={{ marginTop: 3 }} />
            <span><b style={{ font: `600 12px ${sans}`, color: C.ink }}>The attachments</b><span style={{ display: "block", font: `11px ${sans}`, color: C.stone }}>Bills, photographs and scans. Makes the file much heavier.</span></span>
          </label>
        </div>

        <div style={{ display: "flex", alignItems: "center", gap: 10, background: heavy ? C.amberSoft : C.greenSoft, border: `1px solid ${heavy ? C.amber : C.green}`, borderRadius: 11, padding: 12, flexWrap: "wrap" }}>
          <div style={{ flex: 1, minWidth: 160 }}>
            <div style={{ font: `600 13px ${sans}`, color: heavy ? C.amber : C.green }}>{nRows} rows · about {kb > 1024 ? (kb / 1024).toFixed(1) + " MB" : kb + " KB"}{fmt === "pdf" ? ` · ${pages} pages` : ""}</div>
            <div style={{ font: `11px ${sans}`, color: C.inkSoft, marginTop: 3 }}>
              {heavy ? "That is a lot to send. Narrow the period or leave the attachments out — the person on the other end rarely needs everything."
                     : "A sensible size. Only what you asked for goes in."}
            </div>
          </div>
          {heavy && <GoldButton small ghost onClick={() => { setPeriod("current"); setWithAttach(false); toast("Trimmed to what is on your screen", "green"); }}>Trim it</GoldButton>}
        </div>

        <div style={{ background: "#fff", border: `1px solid ${C.line}`, borderRadius: 11, padding: 12, marginTop: 12 }}>
          <div style={{ font: `600 9px ${sans}`, letterSpacing: "0.06em", textTransform: "uppercase", color: C.stone, marginBottom: 7 }}>Every page will carry</div>
          <div style={{ font: `12px ${sans}`, color: C.inkSoft, lineHeight: 1.7 }}>
            <b style={{ color: C.ink }}>MARBELLA GROUP</b> · {activeFirm.firm}<br />
            {activeFirm.name} · GSTIN {activeFirm.gstin} · RERA {activeFirm.rera}<br />
            Generated {stampStr} · Exported by {u.name}, {u.role} — <b style={{ color: C.goldDeep, fontFamily: mono }}>{empId}</b><br />
            <span style={{ font: `11px ${sans}`, color: C.stone }}>Marbella Group — internal. Do not forward outside the company.</span>
          </div>
        </div>

        <div style={{ display: "flex", gap: 10, marginTop: 14, flexWrap: "wrap" }}>
          <GreenButton onClick={doExport}><span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Download size={14} /> {dupe ? "Make it anyway" : "Export"} · {fmt.toUpperCase()}</span></GreenButton>
          <GoldButton ghost onClick={onClose}>Cancel</GoldButton>
        </div>
        <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 10 }}>PDF opens the print dialog — choose “Save as PDF”. Excel and CSV download straight away. A shared document vault, so the same file is never made twice, comes with the backend.</div>
      </div>
    </Overlay>
  );
}

function ExportButton({ onClick, small }) {
  return (
    <GoldButton small={small !== false} ghost onClick={onClick}>
      <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Download size={13} /> Export</span>
    </GoldButton>
  );
}

function CamStyles() {
  return <style>{`
@keyframes mbRec{0%,100%{opacity:1}50%{opacity:.25}}
@keyframes mbNoise{0%{background-position:0 0}100%{background-position:120px 90px}}
@keyframes mbSweepCam{0%{transform:translateY(-100%)}100%{transform:translateY(320%)}}
`}</style>;
}
function CamFrame({ cam, big }) {
  const h = big ? 300 : 116;
  return (
    <div style={{ position: "relative", height: h, borderRadius: 10, overflow: "hidden", background: cam.on ? "#12203A" : "#1A1A1E", border: `1px solid ${cam.on ? C.line : C.stone}` }}>
      {cam.on ? (<>
        <div style={{ position: "absolute", inset: 0, background: "linear-gradient(160deg,#16345F,#0E2244 55%,#1B3C6B)" }} />
        <div style={{ position: "absolute", inset: 0, opacity: 0.16, backgroundImage: "radial-gradient(#fff 1px, transparent 1px)", backgroundSize: "3px 3px", animation: "mbNoise 2.4s linear infinite" }} />
        <div style={{ position: "absolute", left: 0, right: 0, height: "34%", background: "linear-gradient(180deg,transparent,rgba(255,255,255,.06),transparent)", animation: "mbSweepCam 4.5s linear infinite" }} />
        {/* crude scene shapes so it reads as a room, not a blank box */}
        <div style={{ position: "absolute", left: "8%", bottom: "12%", width: "26%", height: "42%", background: "rgba(255,255,255,.06)", borderRadius: 4 }} />
        <div style={{ position: "absolute", left: "40%", bottom: "12%", width: "18%", height: "58%", background: "rgba(255,255,255,.09)", borderRadius: 4 }} />
        <div style={{ position: "absolute", right: "9%", bottom: "12%", width: "22%", height: "34%", background: "rgba(255,255,255,.05)", borderRadius: 4 }} />
        <div style={{ position: "absolute", left: 0, right: 0, bottom: "12%", height: 1, background: "rgba(255,255,255,.14)" }} />
        <div style={{ position: "absolute", top: 8, left: 9, display: "flex", alignItems: "center", gap: 6 }}>
          <span style={{ width: 7, height: 7, borderRadius: "50%", background: "#E0705C", animation: "mbRec 1.4s ease-in-out infinite" }} />
          <span style={{ font: `600 9px ${mono}`, color: "#fff", letterSpacing: "0.08em" }}>LIVE</span>
        </div>
        <div style={{ position: "absolute", bottom: 7, left: 9, right: 9, display: "flex", justifyContent: "space-between", font: `9px ${mono}`, color: "rgba(255,255,255,.75)" }}>
          <span>{cam.id}</span><span>{new Date().toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit", second: "2-digit" })}</span>
        </div>
      </>) : (
        <div style={{ position: "absolute", inset: 0, display: "grid", placeItems: "center", color: C.stone, font: `11px ${sans}`, textAlign: "center", padding: 10 }}>
          <div><Video size={20} color={C.stone} /><div style={{ marginTop: 6 }}>Camera offline</div></div>
        </div>
      )}
    </div>
  );
}
function CameraLive({ cam, onClose, onLogged }) {
  const mob = useIsMobile();
  useEffect(() => { onLogged && onLogged(cam); }, []);
  return (
    <Overlay onClose={onClose} width={660}>
      <CamStyles />
      <div style={{ padding: mob ? 16 : 22 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10, flexWrap: "wrap" }}>
          <Video size={17} color={C.gold} /><Eyebrow>Live view</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>
        <CamFrame cam={cam} big />
        <div style={{ display: "flex", alignItems: "flex-start", gap: 10, marginTop: 12, flexWrap: "wrap" }}>
          <div style={{ flex: 1, minWidth: 180 }}>
            <div style={{ font: `600 14px ${sans}`, color: C.ink }}>{cam.place}</div>
            <div style={{ font: `12px ${sans}`, color: C.stone }}>{cam.who !== "—" ? `${cam.who} · ${cam.role}` : "Not assigned to anyone"} · {cam.note}</div>
          </div>
          <Pill tone={cam.on ? "green" : "stone"}>{cam.on ? "live" : "offline"}</Pill>
        </div>
        <div style={{ background: C.goldTint, border: `1px solid ${C.goldSoft}`, borderRadius: 10, padding: 11, marginTop: 12, display: "flex", gap: 9, font: `11px ${sans}`, color: C.inkSoft }}>
          <ShieldCheck size={15} color={C.goldDeep} style={{ flexShrink: 0 }} />
          <div><b style={{ color: C.inkDeep }}>This viewing is on the record.</b> Your name and the time are written to the camera log, and the person at that desk can see that you looked. Cameras cover working areas only.</div>
        </div>
        <div style={{ display: "flex", gap: 9, marginTop: 12, flexWrap: "wrap" }}>
          <GoldButton small ghost onClick={() => (async () => {
              const r = await logGate({ outcome: "permit", label: `Camera snapshot — ${cam.name}`, post: cam.name, note: "Still captured from the live wall." });
              if (r) toast("Snapshot recorded in the gate log", "green");
            })()}><span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Camera size={13} /> Snapshot</span></GoldButton>
          <GoldButton small onClick={onClose}>Close</GoldButton>
        </div>
        <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 10 }}>Real camera streams connect through the site NVR with the backend. What you see here is the player and the rules around it.</div>
      </div>
    </Overlay>
  );
}
function CameraWall({ compact }) {
  const mob = useIsMobile();
  const [cams, setCams] = useState(CAMERAS_SEED);
  const [live, setLive] = useState(null);
  const [log, setLog] = useState([]);
  const [assign, setAssign] = useState(null);
  const online = cams.filter(c => c.on).length;
  return (
    <Card pad={mob ? 14 : 20} style={{ marginBottom: 16 }}>
      <CamStyles />
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10, flexWrap: "wrap" }}>
        <Video size={16} color={C.goldDeep} /><span style={{ font: `600 13px ${sans}`, color: C.ink }}>Cameras</span>
        <Pill tone="green">{online} live</Pill>
        {log.length > 0 && <Pill tone="stone">{log.length} viewed today</Pill>}
        <span style={{ marginLeft: "auto", font: `11px ${sans}`, color: C.stone }}>Chairman only</span>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr 1fr" : "repeat(3,1fr)", gap: 9 }}>
        {cams.slice(0, compact ? 3 : 6).map(c => (
          <div key={c.id} onClick={() => c.on && setLive(c)} style={{ cursor: c.on ? "pointer" : "default" }}>
            <CamFrame cam={c} />
            <div style={{ font: `600 11px ${sans}`, color: C.ink, marginTop: 6, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{c.place}</div>
            <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 2 }}>
              <span style={{ font: `10px ${sans}`, color: C.stone, flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{c.who !== "—" ? c.who : "unassigned"}</span>
              <button onClick={(e) => { e.stopPropagation(); setAssign(c); }} style={{ background: "none", border: "none", cursor: "pointer", color: C.gold, font: `600 10px ${sans}`, padding: 0 }}>assign</button>
            </div>
          </div>
        ))}
      </div>
      {log.length > 0 && (
        <div style={{ marginTop: 12, paddingTop: 10, borderTop: `1px solid ${C.line}` }}>
          <div style={{ font: `600 9px ${sans}`, letterSpacing: "0.06em", textTransform: "uppercase", color: C.stone, marginBottom: 6 }}>Who looked, and when</div>
          {log.slice(0, 3).map((l, i) => (
            <div key={i} style={{ font: `11px ${sans}`, color: C.inkSoft, padding: "3px 0" }}>Nitish Walia viewed <b style={{ color: C.ink }}>{l.place}</b> at {l.at}</div>
          ))}
        </div>
      )}
      {live && <CameraLive cam={live} onClose={() => setLive(null)} onLogged={(c) => setLog(l => [{ place: c.place, at: new Date().toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" }) }, ...l])} />}
      {assign && (
        <Overlay onClose={() => setAssign(null)} width={460}>
          <div style={{ padding: mob ? 18 : 22 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
              <Video size={16} color={C.gold} /><Eyebrow>Assign the camera</Eyebrow>
              <button onClick={() => setAssign(null)} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
            </div>
            <h2 style={{ font: `400 19px ${serif}`, margin: "4px 0 4px" }}>{assign.place}</h2>
            <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 12 }}>Whoever this camera is assigned to will see it on their own profile, and will know when it is watched.</div>
            <label style={{ ...lbl, fontSize: 9 }}>Assigned to</label>
            <select defaultValue={assign.who} onChange={e => { const v = e.target.value; setCams(a => a.map(c => c.id === assign.id ? { ...c, who: v, role: (Object.values(USERS).find(u => u.name === v) || {}).role || "—" } : c)); }} style={{ ...sel, margin: "5px 0 12px" }}>
              <option value="—">Nobody — open area</option>
              {Object.values(USERS).map(u => <option key={u.key}>{u.name}</option>)}
            </select>
            <GoldButton small onClick={() => { toast(`${assign.place} assigned`, "green"); setAssign(null); }}>Save</GoldButton>
          </div>
        </Overlay>
      )}
      <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 10 }}>Cameras are placed in working areas only, everyone is told they exist, and every viewing is logged — including yours.</div>
    </Card>
  );
}

/* ===== CAST TO A SCREEN — with consent when money is on it ===== */
const TVS = [
  { id: "tv1", name: "Boardroom — LG OLED", how: "Smart View", room: "SCO 2417 · Boardroom" },
  { id: "tv2", name: "Site office — Samsung", how: "Smart View", room: "Marbella Grand" },
  { id: "tv3", name: "Chromecast — Meeting 2", how: "Google Cast", room: "SCO 2417" },
  { id: "tv4", name: "Apple TV — Chairman's cabin", how: "AirPlay", room: "SCO 2417" },
];
function CastPanel({ tab, onClose }) {
  const mob = useIsMobile();
  const MONEY = ["expenses", "sales", "masters", "accounts", "cost", "tax", "overview"];
  const sensitive = MONEY.includes(tab);
  const [pick, setPick] = useState(null);
  const [stage, setStage] = useState("pick");
  const [approver, setApprover] = useState("P. Nair · Accounts Head");
  useEffect(() => {
    if (stage !== "waiting") return;
    const t = setTimeout(() => setStage("approved"), 2600);
    return () => clearTimeout(t);
  }, [stage]);
  const go = (tv) => {
    setPick(tv);
    if (sensitive) setStage("consent"); else { setStage("casting"); toast(`Casting to ${tv.name}`, "green"); }
  };
  return (
    <Overlay onClose={onClose} width={520}>
      <div style={{ padding: mob ? 18 : 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 6 }}>
          <Share2 size={17} color={C.gold} /><Eyebrow>Cast this screen</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>

        {stage === "pick" && (<>
          <h2 style={{ font: `400 20px ${serif}`, margin: "4px 0 4px" }}>Put it on the big screen.</h2>
          <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 12 }}>Screens found on this network — LG and Samsung Smart View, Google Cast and AirPlay.</div>
          {sensitive && (
            <div style={{ background: C.amberSoft, border: `1px solid ${C.amber}`, borderRadius: 10, padding: 11, marginBottom: 12, display: "flex", gap: 9, font: `12px ${sans}`, color: C.inkSoft }}>
              <Lock size={15} color={C.amber} style={{ flexShrink: 0 }} />
              <div><b style={{ color: C.inkDeep }}>This screen shows money.</b> Someone responsible has to approve before it goes on a television.</div>
            </div>
          )}
          {TVS.map((tv, i) => (
            <div key={tv.id} onClick={() => go(tv)} style={{ cursor: "pointer", display: "flex", alignItems: "center", gap: 11, padding: "11px 0", borderTop: i ? `1px solid ${C.lineSoft}` : `1px solid ${C.line}` }}>
              <div style={{ width: 34, height: 26, borderRadius: 4, border: `2px solid ${C.inkDeep}`, flexShrink: 0, background: C.paper }} />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ font: `600 13px ${sans}`, color: C.ink }}>{tv.name}</div>
                <div style={{ font: `11px ${sans}`, color: C.stone }}>{tv.room} · {tv.how}</div>
              </div>
              <ChevronRight size={16} color={C.stone} />
            </div>
          ))}
        </>)}

        {stage === "consent" && (<>
          <h2 style={{ font: `400 20px ${serif}`, margin: "4px 0 4px" }}>Who is approving this?</h2>
          <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 12 }}>Financial figures are about to appear on <b style={{ color: C.ink }}>{pick.name}</b> in {pick.room}. The approval and the time are logged.</div>
          <label style={{ ...lbl, fontSize: 9 }}>Ask</label>
          <select value={approver} onChange={e => setApprover(e.target.value)} style={{ ...sel, margin: "5px 0 12px" }}>
            {["P. Nair · Accounts Head", "R. Khanna · Purchase Manager", "Simran Kaur · HR Head", "Nitish Walia · Chairman"].map(x => <option key={x}>{x}</option>)}
          </select>
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
            <GoldButton onClick={() => { setStage("waiting"); toast(`Approval sent to ${approver.split("·")[0].trim()}`, "gold"); }}>Ask for approval</GoldButton>
            <GoldButton ghost onClick={() => setStage("pick")}>Back</GoldButton>
          </div>
        </>)}

        {stage === "waiting" && (
          <div style={{ textAlign: "center", padding: "22px 0" }}>
            <div style={{ width: 34, height: 34, border: `3px solid ${C.gold}`, borderTopColor: "transparent", borderRadius: "50%", margin: "0 auto 14px", animation: "mbSpin .8s linear infinite" }} />
            <IntakeStyles />
            <div style={{ font: `600 14px ${sans}`, color: C.ink }}>Waiting for {approver.split("·")[0].trim()}</div>
            <div style={{ font: `12px ${sans}`, color: C.stone, marginTop: 5 }}>A pop-up has gone to their app. Nothing appears on the television until they tap approve.</div>
          </div>
        )}

        {(stage === "approved" || stage === "casting") && (
          <div style={{ textAlign: "center", padding: "16px 0" }}>
            <div style={{ width: 40, height: 40, borderRadius: "50%", background: C.greenSoft, display: "grid", placeItems: "center", margin: "0 auto 12px" }}><Check size={21} color={C.green} /></div>
            <h2 style={{ font: `400 20px ${serif}`, margin: "0 0 6px" }}>Now showing on {pick.name}</h2>
            <div style={{ font: `12px ${sans}`, color: C.stone, lineHeight: 1.6, marginBottom: 14 }}>
              {pick.room} · {pick.how}{stage === "approved" ? <><br />Approved by <b style={{ color: C.ink }}>{approver}</b> at {new Date().toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" })}</> : null}
            </div>
            <div style={{ display: "flex", gap: 9, justifyContent: "center", flexWrap: "wrap" }}>
              <GoldButton small ghost onClick={() => { toast("Stopped casting", "stone"); onClose(); }}>Stop casting</GoldButton>
              <GoldButton small onClick={onClose}>Done</GoldButton>
            </div>
          </div>
        )}
        <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 12 }}>Real Smart View, Google Cast and AirPlay handshakes are done by the device with the backend. The approval rule around them is real.</div>
      </div>
    </Overlay>
  );
}

function AccessConsole({ onActAs }) {
  const mob = useIsMobile();
  const { saveGrants, grants: savedGrants } = useProc();
  /* Seeded from what the server holds, so the console opens on the real state
     rather than on a default that was never anybody's actual access. */
  const [grants, setGrants] = useState(() => {
    const base = DEFAULT_GRANTS();
    if (!savedGrants) return base;
    Object.entries(savedGrants).forEach(([k, areas]) => { base[k] = { ...base[k], ...areas }; });
    return base;
  });
  const [roles, setRoles] = useState(Object.keys(USERS));
  const [pick, setPick] = useState("purchase");
  const [newRole, setNewRole] = useState(false);
  const [newUser, setNewUser] = useState(false);
  const [nr, setNr] = useState({ name: "", base: "purchase", dept: "Purchase" });
  const [nu, setNu] = useState({ name: "", role: "purchase", phone: "", email: "" });
  const [added, setAdded] = useState([]);
  const cell = { ...inp, margin: 0, padding: "9px 10px", fontSize: 13, boxSizing: "border-box" };
  const flip = (area, power) => setGrants(g => ({ ...g, [pick]: { ...g[pick], [area]: { ...g[pick][area], [power]: !g[pick][area][power] } } }));
  const u = USERS[pick] || { name: pick, role: pick, dept: "—" };
  const count = (r) => { let n = 0; AREA_GROUPS.forEach(([, as]) => as.forEach(([a]) => { if (grants[r] && grants[r][a] && grants[r][a].view) n++; })); return n; };
  const totalAreas = AREA_GROUPS.reduce((a, g) => a + g[1].length, 0);

  return (
    <div>
      <Eyebrow>Chairman only · access</Eyebrow>
      <h1 style={{ font: `400 25px ${serif}`, margin: "6px 0 4px" }}>Who can see what.</h1>
      <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 14 }}>Step into anyone's shoes, or change what they are allowed to touch. Nobody else in the company can open this page.</div>

      {/* act as */}
      <Card pad={mob ? 14 : 20} style={{ marginBottom: 16, borderColor: C.goldSoft }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4, flexWrap: "wrap" }}>
          <Eye size={16} color={C.goldDeep} /><span style={{ font: `600 13px ${sans}`, color: C.ink }}>See the app as someone else</span>
        </div>
        <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 12 }}>Their exact screen — their tabs, their buttons, their limits. You can come back with one tap.</div>
        <div style={{ display: mob ? "block" : "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 9 }}>
          {roles.filter(r => r !== "admin").map(r => {
            const p = USERS[r] || { name: r, role: r, dept: "—" };
            return (
              <div key={r} style={{ background: C.paper, border: `1px solid ${C.line}`, borderRadius: 11, padding: 11, marginBottom: mob ? 9 : 0 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 9 }}>
                  <div style={{ width: 30, height: 30, borderRadius: "50%", background: C.inkDeep, color: "#fff", display: "grid", placeItems: "center", font: `700 12px ${serif}`, flexShrink: 0 }}>{p.name[0]}</div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ font: `600 12px ${sans}`, color: C.ink, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{p.name}</div>
                    <div style={{ font: `10px ${sans}`, color: C.stone }}>{p.role}</div>
                  </div>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 7, marginTop: 9, flexWrap: "wrap" }}>
                  <span style={{ font: `10px ${sans}`, color: C.stone }}>{count(r)}/{totalAreas} areas</span>
                  <GoldButton small onClick={() => onActAs(r)}>Act as</GoldButton>
                </div>
              </div>
            );
          })}
        </div>
      </Card>

      {/* permission grid */}
      <Card pad={mob ? 14 : 20} style={{ marginBottom: 16 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10, flexWrap: "wrap" }}>
          <ShieldCheck size={16} color={C.goldDeep} /><span style={{ font: `600 13px ${sans}`, color: C.ink }}>What they are allowed to touch</span>
          <select value={pick} onChange={e => setPick(e.target.value)} style={{ ...sel, margin: 0, width: mob ? "100%" : 230, padding: "7px 9px", fontSize: 12, marginLeft: mob ? 0 : "auto", marginTop: mob ? 8 : 0 }}>
            {roles.map(r => <option key={r} value={r}>{(USERS[r] || {}).name || r} — {(USERS[r] || {}).role || r}</option>)}
          </select>
        </div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 12 }}>
          {POWERS.map(([k, l]) => (
            <span key={k} style={{ display: "inline-flex", alignItems: "center", gap: 6, font: `600 11px ${sans}`, color: C.inkSoft }}>
              <span style={{ width: 11, height: 11, borderRadius: 3, background: POWER_TONE[k], display: "inline-block" }} />{l}
            </span>
          ))}
          <span style={{ marginLeft: mob ? 0 : "auto", font: `11px ${sans}`, color: C.stone }}>Tap a colour to give or take it away</span>
        </div>
        {AREA_GROUPS.map(([grp, areas]) => (
          <div key={grp} style={{ marginBottom: 12 }}>
            <div style={{ font: `600 9px ${sans}`, letterSpacing: "0.08em", textTransform: "uppercase", color: C.stone, marginBottom: 6 }}>{grp}</div>
            {areas.map(([a, label]) => {
              const g = (grants[pick] && grants[pick][a]) || {};
              return (
                <div key={a} style={{ display: "flex", alignItems: "center", gap: 9, padding: "7px 0", borderTop: `1px solid ${C.lineSoft}`, flexWrap: "wrap" }}>
                  <span style={{ flex: 1, minWidth: 120, font: `12px ${sans}`, color: g.view ? C.ink : C.stone, fontWeight: g.view ? 600 : 400 }}>{label}</span>
                  <div style={{ display: "flex", gap: 4, borderRadius: 20, overflow: "hidden", border: `1px solid ${C.line}` }}>
                    {POWERS.map(([k, l]) => (
                      <button key={k} onClick={() => flip(a, k)} title={l}
                        style={{ cursor: "pointer", border: "none", padding: "6px 11px", font: `600 10px ${sans}`, transition: "all .18s",
                          background: g[k] ? POWER_TONE[k] : "#fff", color: g[k] ? "#fff" : C.stone, opacity: g[k] ? 1 : 0.75 }}>
                        {l.split(" ")[0]}
                      </button>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        ))}
        <div style={{ display: "flex", gap: 9, flexWrap: "wrap", alignItems: "center", paddingTop: 10, borderTop: `2px solid ${C.gold}` }}>
          <span style={{ font: `12px ${sans}`, color: C.inkSoft, flex: 1, minWidth: 150 }}>{u.name} can currently open <b style={{ color: C.ink }}>{count(pick)}</b> of {totalAreas} areas.</span>
          <GoldButton small onClick={() => (async () => {
                    /* EDIT 8 of 10: this used to announce a change and forget it the
                       moment the screen closed. Nobody's access ever moved. It writes
                       rows now, sealed against the administrator who made the change. */
                    const grid = grants[pick] || {};
                    const changes = [];
                    AREA_GROUPS.forEach(([, items]) => items.forEach(([area]) =>
                      POWERS.forEach(([power]) => changes.push({ area, power, granted: !!(grid[area] || {})[power] }))));
                    const saved = await saveGrants(pick, changes);
                    if (saved) toast(`Access saved for ${u.name} — it applies the next time they sign in`, "green");
                  })()}>Save these permissions</GoldButton>
        </div>
      </Card>

      {/* add role / add user */}
      <div style={{ display: mob ? "block" : "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
        <Card pad={mob ? 14 : 18} style={{ marginBottom: mob ? 14 : 0 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}><Crown size={15} color={C.goldDeep} /><span style={{ font: `600 13px ${sans}`, color: C.ink }}>Create a role</span></div>
          <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 10 }}>Anything you like — Site Cashier, Sales Head, Auditor. Start it from a role that already exists and trim it down.</div>
          {!newRole ? <GoldButton small onClick={() => setNewRole(true)}><span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Plus size={13} /> New role</span></GoldButton> : (<>
            <label style={{ ...lbl, fontSize: 9 }}>Name the role</label>
            <input value={nr.name} onChange={e => setNr(s => ({ ...s, name: e.target.value }))} placeholder="e.g. Sales Head" style={{ ...cell, margin: "5px 0 9px" }} />
            <label style={{ ...lbl, fontSize: 9 }}>Copy the access of</label>
            <select value={nr.base} onChange={e => setNr(s => ({ ...s, base: e.target.value }))} style={{ ...sel, margin: "5px 0 9px" }}>
              {roles.map(r => <option key={r} value={r}>{(USERS[r] || {}).role || r}</option>)}
            </select>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
              <GoldButton small onClick={() => {
                if (!nr.name.trim()) return toast("Give the role a name", "amber");
                const key = nr.name.trim().toLowerCase().replace(/\s+/g, "_");
                USERS[key] = { name: nr.name.trim(), role: nr.name.trim(), tier: 2, key, dept: nr.dept };
                NAV[key] = NAV[nr.base] || NAV.purchase;
                setGrants(g => ({ ...g, [key]: JSON.parse(JSON.stringify(g[nr.base])) }));
                setRoles(r => [...r, key]); setPick(key); setNewRole(false); setNr({ name: "", base: "purchase", dept: "Purchase" });
                toast(`Role "${nr.name.trim()}" created — trim its access below`, "green");
              }}>Create it</GoldButton>
              <GoldButton small ghost onClick={() => setNewRole(false)}>Cancel</GoldButton>
            </div>
          </>)}
        </Card>

        <Card pad={mob ? 14 : 18}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}><UserPlus size={15} color={C.goldDeep} /><span style={{ font: `600 13px ${sans}`, color: C.ink }}>Add a user</span></div>
          <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 10 }}>Give a person a login against one of the roles. HR still issues their Marbella ID.</div>
          {!newUser ? <GoldButton small onClick={() => setNewUser(true)}><span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Plus size={13} /> New user</span></GoldButton> : (<>
            <label style={{ ...lbl, fontSize: 9 }}>Name</label>
            <input value={nu.name} onChange={e => setNu(s => ({ ...s, name: e.target.value }))} placeholder="e.g. P. Grewal" style={{ ...cell, margin: "5px 0 9px" }} />
            <label style={{ ...lbl, fontSize: 9 }}>Role</label>
            <select value={nu.role} onChange={e => setNu(s => ({ ...s, role: e.target.value }))} style={{ ...sel, margin: "5px 0 9px" }}>
              {roles.map(r => <option key={r} value={r}>{(USERS[r] || {}).role || r}</option>)}
            </select>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
              <GoldButton small onClick={() => {
                if (!nu.name.trim()) return toast("Name the person", "amber");
                setAdded(a => [{ name: nu.name.trim(), role: (USERS[nu.role] || {}).role || nu.role }, ...a]);
                setNewUser(false); setNu({ name: "", role: "purchase", phone: "", email: "" });
                toast(`${nu.name.trim()} added — an OTP goes to their mobile and email`, "green");
              }}>Add them</GoldButton>
              <GoldButton small ghost onClick={() => setNewUser(false)}>Cancel</GoldButton>
            </div>
          </>)}
          {added.map((a, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 0", borderTop: `1px solid ${C.lineSoft}`, marginTop: i ? 0 : 10, font: `12px ${sans}` }}>
              <Check size={13} color={C.green} /><span style={{ color: C.ink, fontWeight: 600 }}>{a.name}</span><span style={{ color: C.stone }}>· {a.role}</span><Pill tone="amber">awaiting OTP</Pill>
            </div>
          ))}
        </Card>
      </div>
      <div style={{ display: "flex", alignItems: "flex-start", gap: 8, marginTop: 14, font: `11px ${sans}`, color: C.stone }}>
        <Info size={13} color={C.goldDeep} style={{ flexShrink: 0, marginTop: 1 }} />
        Acting as someone changes only what you see — it never signs anything in their name, and the fact that you looked is written into the log.
      </div>
    </div>
  );
}

export function Shell({ userKey: realKey, onLogout }) {
  const mob = useIsMobile();
  const [actAs, setActAs] = useState(null);
  const [returnTab, setReturnTab] = useState(null);
  const userKey = actAs || realKey;
  const u = USERS[userKey], nav = NAV[userKey];
  const [tab, setTab] = useState(nav[0][0]);
  const [reporting, setReporting] = useState(false);
  const [showCalc, setShowCalc] = useState(false);
  const [casting, setCasting] = useState(false);
  const canCalc = ["Purchase", "Accounts", "Admin"].includes(u.dept);
  const [task, setTask] = useState(null);
  useEffect(() => { setTab(nav[0][0]); }, [userKey]);
  const tier = u.tier;
  const runTask = (t) => {
    if (t.resume) { setTask({ kind: t.resume.type, prefill: t.resume.data }); return; }
    const nav2 = { intent: "intent", vendors: "vendors", inventory: "inventory", reconcile: "accounts", letter: "letters" };
    if (t.id === "report") return setReporting(true);
    if (["po", "pr", "upload", "requirement", "enroll"].includes(t.id)) return setTask({ kind: t.id });
    if (nav2[t.id]) return setTab(nav2[t.id]);
  };
  const modals = (
    <>
      {reporting && <ReportModal by={u.name} onClose={() => setReporting(false)} />}
      {casting && <CastPanel tab={tab} onClose={() => setCasting(false)} />}
      {showCalc && <FigureHelper onClose={() => setShowCalc(false)} />}
      {task?.kind === "po" && <CreatePO prefill={task.prefill} onClose={() => setTask(null)} />}
      {task?.kind === "pr" && <RaisePR prefill={task.prefill} userKey={userKey} onClose={() => setTask(null)} />}
      {task?.kind === "upload" && <TaskModal title="Upload a document" icon={Upload} onClose={() => setTask(null)}><Uploader /></TaskModal>}
      {task?.kind === "requirement" && <TaskModal title="Request material from store" icon={ClipboardList} onClose={() => setTask(null)}><RequirementForm from={u.name} onDone={() => setTask(null)} compact /></TaskModal>}
      {task?.kind === "enroll" && <EnrollPerson onClose={() => setTask(null)} />}
    </>
  );
  if (mob) {
    return (
      <div style={{ minHeight: "100vh", font: `14px ${sans}`, color: C.ink, background: C.paper, maxWidth: "100vw", overflowX: "hidden" }}>
        <div style={{ background: C.ink, color: "#E8ECF4", position: "sticky", top: 0, zIndex: 30, borderBottom: `2px solid ${TIER_COLOR[tier]}`, maxWidth: "100vw", overflow: "hidden" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "12px 16px" }}>
            <img src={CREST} alt="Marbella" style={{ height: 28, display: "block" }} />
            <div style={{ font: `600 11px ${sans}`, letterSpacing: "0.18em" }}>MARBELLA</div>
            <div style={{ marginLeft: "auto", display: "flex", alignItems: "center", gap: 12 }}>
              <div style={{ width: 28, height: 28, borderRadius: "50%", background: TIER_COLOR[tier], display: "grid", placeItems: "center", color: "#fff", font: `700 12px ${serif}` }}>{u.name[0]}</div>
              <button onClick={onLogout} style={{ background: "none", border: "none", color: "#8793A8", cursor: "pointer", display: "grid", placeItems: "center" }}><LogOut size={17} /></button>
            </div>
          </div>
          <div style={{ display: "flex", gap: 8, padding: "0 12px 12px", overflowX: "auto", width: "100%", maxWidth: "100vw", boxSizing: "border-box", scrollbarWidth: "none" }}>
            {nav.map(([k, label, Icon]) => (
              <button key={k} onClick={() => setTab(k)} style={{ display: "inline-flex", alignItems: "center", gap: 7, cursor: "pointer", whiteSpace: "nowrap", background: tab === k ? "rgba(168,135,62,.18)" : "transparent", color: tab === k ? "#F3EBD7" : "#9AA4B6", border: `1px solid ${tab === k ? C.gold : "rgba(255,255,255,.12)"}`, padding: "8px 12px", borderRadius: 20, font: `600 12px ${sans}` }}><Icon size={14} /> {label}</button>
            ))}
          </div>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 16px", background: "#fff", borderBottom: `1px solid ${C.line}` }}>
          <MasterSearch /><Clock12 compact />
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 16px", background: "#fff", borderBottom: `1px solid ${C.line}` }}>
          <FirmSwitcher compact /><span style={{ font: `11px ${sans}`, color: C.stone }}>uploads file here</span>
          {canCalc && <button onClick={() => setShowCalc(true)} style={{ marginLeft: "auto", cursor: "pointer", border: `1px solid ${C.line}`, background: "#fff", borderRadius: 20, padding: "7px 11px", display: "inline-flex", alignItems: "center", gap: 6, color: C.goldDeep, font: `600 12px ${sans}` }}><Calculator size={13} /> ₹ Calc</button>}
          <button onClick={() => setCasting(true)} title="Cast to a screen" style={{ cursor: "pointer", border: `1px solid ${C.line}`, background: "#fff", borderRadius: 20, padding: "7px 11px", display: "inline-flex", alignItems: "center", gap: 6, color: C.goldDeep, font: `600 12px ${sans}` }}><Share2 size={13} /> Cast</button>
            <button onClick={() => setReporting(true)} style={{ cursor: "pointer", border: `1px solid ${C.line}`, background: "#fff", borderRadius: 20, padding: "7px 11px", display: "inline-flex", alignItems: "center", gap: 6, color: C.goldDeep, font: `600 12px ${sans}` }}><Flag size={13} /> Report</button>
        </div>
        {actAs && <ActingBanner who={USERS[actAs]} onExit={() => { setActAs(null); if (returnTab) setTimeout(() => setTab(returnTab), 0); toast("Back to your own view", "green"); }} />}
        <div style={{ padding: 16, paddingBottom: 104 }}><NewTaskLauncher userKey={userKey} onRun={runTask} /><IncentiveBanner userKey={userKey} /><CalendarNudge userKey={userKey} /><Views tab={tab} go={setTab} userKey={userKey} onActAs={(r) => { setReturnTab(tab); setActAs(r); toast(`Now seeing the app as ${USERS[r].name} — ${USERS[r].role}`, "gold"); }} /></div>
        <CoachLayer userKey={userKey} />
        {modals}
      </div>
    );
  }
  return (
    <div style={{ display: "grid", gridTemplateColumns: "232px 1fr", minHeight: "100vh", font: `14px ${sans}`, color: C.ink, background: C.paper }}>
      <aside style={{ background: C.ink, color: "#C6CEDD", position: "relative", padding: "22px 16px", display: "flex", flexDirection: "column" }}>
        <div style={{ position: "absolute", left: 0, top: 0, bottom: 0, width: 3, background: TIER_COLOR[tier] }} />
        <div style={{ display: "flex", alignItems: "center", gap: 9, marginBottom: 26, paddingLeft: 4 }}>
          <img src={CREST} alt="Marbella" style={{ height: 32, display: "block" }} />
          <div style={{ font: `600 11px ${sans}`, letterSpacing: "0.18em" }}>MARBELLA</div>
        </div>
        {nav.map(([k, label, Icon]) => (
          <button key={k} onClick={() => setTab(k)} style={{ display: "flex", alignItems: "center", gap: 11, width: "100%", cursor: "pointer", background: tab === k ? "rgba(168,135,62,.14)" : "transparent", color: tab === k ? "#F3EBD7" : "#9AA4B6", border: "none", borderLeft: `2px solid ${tab === k ? C.gold : "transparent"}`, padding: "11px 12px", borderRadius: 8, font: `600 13px ${sans}`, textAlign: "left", marginBottom: 2 }}><Icon size={16} /> {label}</button>
        ))}
        <div style={{ marginTop: "auto" }}>
          <div style={{ height: 1, background: "rgba(255,255,255,.09)" }} />
          <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "12px 6px 6px" }}>
            <div style={{ width: 32, height: 32, borderRadius: "50%", background: TIER_COLOR[tier], display: "grid", placeItems: "center", color: "#fff", font: `700 13px ${serif}` }}>{u.name[0]}</div>
            <div style={{ lineHeight: 1.3 }}><div style={{ font: `600 12px ${sans}`, color: "#E8ECF4" }}>{u.name}</div><div style={{ font: `10px ${sans}`, color: "#8793A8" }}>{u.role} · T{tier}</div></div>
          </div>
          <button onClick={onLogout} style={{ display: "flex", alignItems: "center", gap: 8, background: "none", border: "none", color: "#8793A8", cursor: "pointer", font: `600 12px ${sans}`, padding: "6px" }}><LogOut size={14} /> Sign out</button>
        </div>
      </aside>
      <main>
        <header style={{ height: 60, borderBottom: `1px solid ${C.line}`, display: "flex", alignItems: "center", gap: 16, padding: "0 26px", background: "#fff" }}>
          <MasterSearch />
          <div style={{ marginLeft: "auto", display: "flex", alignItems: "center", gap: 14 }}>
            {canCalc && <button onClick={() => setShowCalc(true)} style={{ cursor: "pointer", border: `1px solid ${C.line}`, background: "#fff", borderRadius: 20, padding: "7px 13px", display: "inline-flex", alignItems: "center", gap: 6, color: C.goldDeep, font: `600 12px ${sans}` }}><Calculator size={14} /> ₹ Calc</button>}
            <button onClick={() => setCasting(true)} title="Cast to a screen" style={{ cursor: "pointer", border: `1px solid ${C.line}`, background: "#fff", borderRadius: 20, padding: "7px 13px", display: "inline-flex", alignItems: "center", gap: 6, color: C.goldDeep, font: `600 12px ${sans}` }}><Share2 size={14} /> Cast</button>
            <button onClick={() => setReporting(true)} style={{ cursor: "pointer", border: `1px solid ${C.line}`, background: "#fff", borderRadius: 20, padding: "7px 13px", display: "inline-flex", alignItems: "center", gap: 6, color: C.goldDeep, font: `600 12px ${sans}` }}><Flag size={14} /> Report</button>
            <FirmSwitcher />
            <Clock12 />
            <div style={{ position: "relative" }}><Bell size={17} color={C.inkSoft} /><div style={{ position: "absolute", top: -3, right: -3, width: 7, height: 7, borderRadius: "50%", background: C.red }} /></div>
          </div>
        </header>
        {actAs && <ActingBanner who={USERS[actAs]} onExit={() => { setActAs(null); if (returnTab) setTimeout(() => setTab(returnTab), 0); toast("Back to your own view", "green"); }} />}
        <div style={{ padding: 26, paddingBottom: 108 }}><NewTaskLauncher userKey={userKey} onRun={runTask} /><IncentiveBanner userKey={userKey} /><CalendarNudge userKey={userKey} /><Views tab={tab} go={setTab} userKey={userKey} onActAs={(r) => { setReturnTab(tab); setActAs(r); toast(`Now seeing the app as ${USERS[r].name} — ${USERS[r].role}`, "gold"); }} /></div>
      </main>
      <CoachLayer userKey={userKey} />
      {modals}
    </div>
  );
}

/* ============================== BOSS ============================== */
/* ===== TWO SHARED LANDINGS so no button dead-ends ===== */
function FilePreview({ title, meta, lines = [], onClose }) {
  const mob = useIsMobile(); const { activeFirm } = useProc();
  return (
    <Overlay onClose={onClose} width={620}>
      <div style={{ padding: mob ? 18 : 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}>
          <FileText size={18} color={C.gold} /><Eyebrow>Document</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>
        <div style={{ background: "#fff", border: `1px solid ${C.line}`, borderRadius: 12, padding: mob ? 14 : 20 }}>
          <DocHead firm={activeFirm} title={title} docId={meta} compact />
          {lines.length ? lines.map(([k, v], i) => (
            <div key={i} style={{ display: "flex", justifyContent: "space-between", gap: 10, padding: "7px 0", borderTop: i ? `1px solid ${C.lineSoft}` : "none", font: `12px ${sans}` }}>
              <span style={{ color: C.stone }}>{k}</span><span style={{ color: C.ink, fontWeight: 600, textAlign: "right", maxWidth: "62%" }}>{v}</span>
            </div>
          )) : <div style={{ font: `12px ${sans}`, color: C.stone }}>This record is on file.</div>}
          <div style={{ marginTop: 14, background: C.paper, border: `1px dashed ${C.line}`, borderRadius: 10, padding: 16, textAlign: "center" }}>
            <FileText size={26} color={C.stone} />
            <div style={{ font: `12px ${sans}`, color: C.stone, marginTop: 6 }}>The scanned page opens here from the document vault once the backend is connected.</div>
          </div>
        </div>
        <div style={{ display: "flex", gap: 10, marginTop: 14, flexWrap: "wrap" }}>
          <GoldButton small ghost onClick={() => printThis()}><span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Printer size={13} /> Print</span></GoldButton>
          <GoldButton small ghost onClick={() => { downloadFile(`${String(meta || title).replace(/\s+/g, "-")}.txt`, `MARBELLA GROUP\n${title}\n${meta || ""}\n\n${lines.map(([k, v]) => `${k}: ${v}`).join("\n")}`); toast("Downloaded", "green"); }}><span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Download size={13} /> Download</span></GoldButton>
          <GoldButton small onClick={onClose}>Close</GoldButton>
        </div>
      </div>
    </Overlay>
  );
}
function ConfirmAction({ title, intro, lines = [], confirmLabel, doneTitle, doneBody, tone = "gold", extra, onClose }) {
  const mob = useIsMobile();
  const [done, setDone] = useState(false);
  if (done) return (
    <Overlay onClose={onClose} width={480}>
      <div style={{ padding: mob ? 20 : 26, textAlign: "center" }}>
        <div style={{ width: 40, height: 40, borderRadius: "50%", background: C.greenSoft, display: "grid", placeItems: "center", margin: "0 auto 12px" }}><Check size={21} color={C.green} /></div>
        <h2 style={{ font: `400 20px ${serif}`, margin: "0 0 6px" }}>{doneTitle}</h2>
        <div style={{ font: `13px ${sans}`, color: C.stone, lineHeight: 1.6, marginBottom: 16 }}>{doneBody}</div>
        <GoldButton small onClick={onClose}>Done</GoldButton>
      </div>
    </Overlay>
  );
  return (
    <Overlay onClose={onClose} width={540}>
      <div style={{ padding: mob ? 18 : 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 6 }}>
          <FileCheck size={18} color={C.gold} /><Eyebrow>Check before it goes</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>
        <h2 style={{ font: `400 20px ${serif}`, margin: "4px 0 4px" }}>{title}</h2>
        {intro && <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 12 }}>{intro}</div>}
        {lines.length > 0 && (
          <div style={{ background: C.paper, border: `1px solid ${C.line}`, borderRadius: 12, padding: 13, marginBottom: 12 }}>
            {lines.map(([k, v], i) => (
              <div key={i} style={{ display: "flex", justifyContent: "space-between", gap: 10, padding: "7px 0", borderTop: i ? `1px solid ${C.lineSoft}` : "none", font: `12px ${sans}` }}>
                <span style={{ color: C.stone }}>{k}</span><span style={{ color: C.ink, fontWeight: 600, textAlign: "right", maxWidth: "62%" }}>{v}</span>
              </div>
            ))}
          </div>
        )}
        {extra}
        <div style={{ display: "flex", gap: 10, marginTop: 8, flexWrap: "wrap" }}>
          {tone === "green" ? <GreenButton onClick={() => setDone(true)}>{confirmLabel}</GreenButton> : <GoldButton onClick={() => setDone(true)}>{confirmLabel}</GoldButton>}
          <GoldButton ghost onClick={onClose}>Cancel</GoldButton>
        </div>
      </div>
    </Overlay>
  );
}

function GateActivity({ compact }) {
  const mob = useIsMobile();
  const { gateLog, exports, registerExport } = useProc();
  const [openEntry, setOpenEntry] = useState(null);
  const [exp, setExp] = useState(false);
  const [only, setOnly] = useState("all");
  const denies = gateLog.filter(g => g.outcome === "deny");
  const rows = (only === "deny" ? denies : only === "permit" ? gateLog.filter(g => g.outcome === "permit") : gateLog).slice(0, compact ? 4 : 20);
  const byGuard = {};
  denies.forEach(g => { byGuard[g.guard] = (byGuard[g.guard] || 0) + 1; });
  return (
    <Card pad={mob ? 14 : 20} style={{ marginBottom: 16, borderColor: denies.length ? C.amber : C.line }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8, flexWrap: "wrap" }}>
        <ShieldCheck size={16} color={C.goldDeep} /><span style={{ font: `600 13px ${sans}`, color: C.ink }}>What happened at the gate</span>
        {denies.length > 0 && <Pill tone="red">{denies.length} turned away</Pill>}
        <div style={{ marginLeft: "auto", display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center" }}>
          <ExportButton onClick={() => setExp(true)} />
          {[["all", "Everything"], ["deny", "Turned away"], ["permit", "Let in"]].map(([k, l]) => (
            <button key={k} onClick={() => setOnly(k)} style={{ cursor: "pointer", border: `1px solid ${only === k ? C.gold : C.line}`, background: only === k ? C.goldTint : "#fff", color: only === k ? C.goldDeep : C.stone, borderRadius: 20, padding: "4px 10px", font: `600 11px ${sans}` }}>{l}</button>
          ))}
        </div>
      </div>
      {Object.keys(byGuard).length > 0 && (
        <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 10 }}>
          {Object.entries(byGuard).map(([g, n]) => <Pill key={g} tone="stone">{g} turned away {n}</Pill>)}
        </div>
      )}
      {rows.length === 0 ? <div style={{ font: `12px ${sans}`, color: C.stone }}>Nothing logged yet.</div> : rows.map((g, i) => (
        <div key={g.id} style={{ display: "flex", alignItems: "flex-start", gap: 10, padding: "10px 0", borderTop: i ? `1px solid ${C.lineSoft}` : `1px solid ${C.line}` }}>
          <div style={{ width: 28, height: 28, borderRadius: 8, flexShrink: 0, display: "grid", placeItems: "center", background: g.outcome === "permit" ? C.greenSoft : C.redSoft }}>
            {g.outcome === "permit" ? <Check size={15} color={C.green} /> : <X size={15} color={C.red} />}
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
              <span style={{ font: `600 13px ${sans}`, color: C.ink }}>{g.label}</span>
              <Pill tone={g.outcome === "permit" ? "green" : "red"}>{g.outcome === "permit" ? "Let in" : "Turned away"}</Pill>
              {g.plate && <span style={{ font: `11px ${mono}`, color: C.stone }}>{g.plate}</span>}
            </div>
            <div style={{ font: `12px ${sans}`, color: C.stone, marginTop: 3 }}>
              {g.guard} ({g.guardId}) at {g.post} · {fmtAgo(g.at)} · authorised by {g.who} · {g.ev} attachment{g.ev !== 1 ? "s" : ""}
            </div>
            {g.note && <div style={{ font: `12px ${sans}`, color: C.inkSoft, marginTop: 3, fontStyle: "italic" }}>{g.note}</div>}
          </div>
          <GoldButton small ghost onClick={() => setOpenEntry(g)}>Open</GoldButton>
        </div>
      ))}
      <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 10 }}>Every decision a guard makes is written here the moment he makes it — including the ones he turns away.</div>
      {exp && <ExportPanel userKey="admin" title="Gate activity" filterNote={only === "deny" ? "turned away only" : only === "permit" ? "let in only" : ""}
        cols={["Entry", "Outcome", "What", "Vehicle", "Guard", "Post", "Authorised by", "Attachments", "Note"]}
        rows={rows.map(g => [g.id, g.outcome === "permit" ? "Let in" : "Turned away", g.label, g.plate || "—", `${g.guard} (${g.guardId})`, g.post, g.who, g.ev, g.note || ""])}
        trail={rows.slice(0, 8).map(g => [g.id, `${g.outcome === "permit" ? "Permitted" : "Turned away"} at ${g.post}`, g.guard, fmtAgo(g.at)])}
        registry={exports} onRegister={registerExport} onClose={() => setExp(false)} />}
      {openEntry && <FilePreview title={openEntry.label} meta={openEntry.id} onClose={() => setOpenEntry(null)} lines={[["Outcome", openEntry.outcome === "permit" ? "Let in" : "Turned away"], ["Vehicle", openEntry.plate || "—"], ["Guard", `${openEntry.guard} (${openEntry.guardId})`], ["Post", openEntry.post], ["Authorised by", openEntry.who], ["Attachments", `${openEntry.ev} photo/voice`], ["Guard's note", openEntry.note || "—"], ["Logged", fmtAgo(openEntry.at)]]} />}
    </Card>
  );
}

