/* ============================== PURCHASE ============================== */
function wordsIN(n) {
  n = Math.round(Math.abs(Number(n) || 0)); if (!n) return "zero";
  const cr = Math.floor(n / 1e7); n %= 1e7;
  const la = Math.floor(n / 1e5); n %= 1e5;
  const th = Math.floor(n / 1e3); n %= 1e3;
  const p = [];
  if (cr) p.push(cr.toLocaleString("en-IN") + " crore");
  if (la) p.push(la + " lakh");
  if (th) p.push(th + " thousand");
  if (n) p.push(String(n));
  return p.join(" ");
}
