function ClaimDoc({ po, userKey, onClose }) {
  const mob = useIsMobile(); const { vendors, activeFirm } = useProc();
  const d = po.del || {}; const over = d.flag === "over";
  const u = USERS[userKey] || USERS.purchase;
  const v = vendors.find(x => x.name === po.vendor) || {};
  const [email, setEmail] = useState(v.email || "");
  const [wa, setWa] = useState(v.whatsapp || v.phone || "");
  const [chEmail, setChEmail] = useState(true);
  const [chWa, setChWa] = useState(true);
  const [amt, setAmt] = useState(String(Math.abs(d.gap || 0)));
  const [subj, setSubj] = useState(over
    ? `Excess supply against Purchase Order ${po.id} — ${activeFirm.short}`
    : `Credit note request — short supply against Purchase Order ${po.id}`);
  const [body, setBody] = useState(over
    ? `Dear ${po.vendor},\n\nAgainst Purchase Order ${po.id}, our order was for ${d.exp}. The quantity received at site on ${d.at} was ${d.got} — an excess over the ordered quantity.\n\nThe material was tipped before our gate check could be completed. We request you to confirm at your earliest whether the excess is to be regularised by a revised invoice, or collected back at your cost.\n\nWe value the association and request your kind confirmation so the records stay clean at both ends.`
    : `Dear ${po.vendor},\n\nAgainst Purchase Order ${po.id}, our order was for ${d.exp}. The quantity received and taken into store on ${d.at} was ${d.got}, leaving a shortfall.\n\n${d.note}\n\nWe therefore request a credit note for the short-supplied quantity as detailed below. Kindly issue the same against the corresponding invoice so both our records reconcile.\n\nWe value the association and appreciate your prompt support in the matter.`);
  const [sent, setSent] = useState(false);
  const stamp = new Date().toLocaleString("en-IN", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" });
  const claimId = (over ? "MB-EX-" : "MB-CN-") + po.id.replace("PO-", "");
  const [mailSubj, setMailSubj] = useState(over ? `${claimId} — excess supply against ${po.id}` : `${claimId} — credit note request against ${po.id}`);
  const [mailBody, setMailBody] = useState(`Dear ${po.vendor},\n\nPlease find attached ${claimId} regarding ${po.id}.\n\nKindly acknowledge receipt and revert with your confirmation.\n\nRegards,\n${u.name}\n${u.role} · ${activeFirm.firm}\nGSTIN ${activeFirm.gstin} · RERA ${activeFirm.rera}\n${activeFirm.addr}`);
  const send = () => {
    if (!chEmail && !chWa) return toast("Pick at least one channel", "amber");
    if (chEmail && !email.trim()) return toast("Add the vendor's email", "amber");
    if (chWa && !wa.trim()) return toast("Add the WhatsApp number", "amber");
    setSent(true); toast(`${claimId} sent to ${po.vendor}`, "gold");
  };
  const lblS = { ...lbl, fontSize: 9 };
  const cellI = { ...inp, margin: 0, padding: "9px 10px", fontSize: 13, boxSizing: "border-box" };

  if (sent) return (
    <Overlay onClose={onClose} width={560}>
      <div style={{ padding: mob ? 20 : 28, textAlign: "center" }}>
        <img src={CREST} alt="Marbella" style={{ height: 46, display: "block", margin: "0 auto 12px" }} />
        <div style={{ width: 40, height: 40, borderRadius: "50%", background: C.greenSoft, display: "grid", placeItems: "center", margin: "0 auto 12px" }}><Check size={22} color={C.green} /></div>
        <h2 style={{ font: `400 21px ${serif}`, margin: "0 0 6px" }}>{over ? "Excess notice sent" : "Credit note requested"}</h2>
        <div style={{ font: `13px ${sans}`, color: C.stone, lineHeight: 1.6, marginBottom: 16 }}>
          <b style={{ color: C.ink }}>{claimId}</b> issued to {po.vendor}{chEmail ? ` · email ${email}` : ""}{chWa ? ` · WhatsApp ${wa}` : ""}.<br />
          Signed by {u.name}, {u.role} · {stamp}.
        </div>
        <div style={{ background: C.paper, border: `1px solid ${C.line}`, borderRadius: 10, padding: 12, font: `12px ${sans}`, color: C.inkSoft, textAlign: "left", marginBottom: 16 }}>
          Logged against {po.id}. Accounts will see the claim when the vendor's invoice comes up for payment.
        </div>
        <div style={{ display: "flex", gap: 10, justifyContent: "center", flexWrap: "wrap" }}>
          <GoldButton ghost small onClick={() => printThis()}><span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Printer size={13} /> Print hard copy</span></GoldButton>
          <GoldButton small onClick={onClose}>Done</GoldButton>
        </div>
      </div>
    </Overlay>
  );

  return (
    <Overlay onClose={onClose} width={640}>
      <div style={{ padding: mob ? 18 : 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 10 }}>
          <FileText size={18} color={C.gold} /><Eyebrow>{over ? "Excess supply notice" : "Credit note request"}</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>

        {/* letterhead preview */}
        <div style={{ background: "#fff", border: `1px solid ${C.line}`, borderRadius: 12, padding: mob ? 16 : 22, marginBottom: 14 }}>
          <DocHead firm={activeFirm} docId={claimId} when={stamp} />
          <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 4 }}>To</div>
          <div style={{ font: `600 14px ${sans}`, color: C.ink, marginBottom: 12 }}>{po.vendor}</div>
          <label style={lblS}>Subject</label>
          <input value={subj} onChange={e => setSubj(e.target.value)} style={{ ...cellI, margin: "5px 0 12px", fontWeight: 600 }} />
          <label style={lblS}>Letter</label>
          <textarea value={body} onChange={e => setBody(e.target.value)} rows={mob ? 8 : 10} style={{ ...cellI, marginTop: 5, resize: "vertical", lineHeight: 1.6 }} />

          {/* claim table */}
          <div style={{ background: C.paper, border: `1px solid ${C.line}`, borderRadius: 10, padding: 12, marginTop: 14 }}>
            <div style={{ font: `600 10px ${sans}`, letterSpacing: "0.06em", textTransform: "uppercase", color: C.stone, marginBottom: 8 }}>Particulars</div>
            {[["Purchase order", po.id], ["Material", po.item], ["Ordered", d.exp], ["Received at site", d.got], ["Received by", d.by], ["Vehicle / driver", d.who], ["Reached", d.at]].map(([k, val], i) => (
              <div key={k} style={{ display: "flex", justifyContent: "space-between", gap: 10, padding: "5px 0", borderTop: i ? `1px solid ${C.lineSoft}` : "none", font: `12px ${sans}` }}>
                <span style={{ color: C.stone }}>{k}</span><span style={{ color: C.ink, fontWeight: 600, textAlign: "right" }}>{val || "—"}</span>
              </div>
            ))}
            <div style={{ display: "flex", alignItems: "center", gap: 10, marginTop: 10, paddingTop: 10, borderTop: `1px solid ${C.line}`, flexWrap: "wrap" }}>
              <span style={{ font: `600 12px ${sans}`, color: C.inkDeep, flex: 1, minWidth: 130 }}>{over ? "Value of excess supply" : "Credit note claimed"}</span>
              <span style={{ font: `13px ${mono}`, color: C.stone }}>₹</span>
              <input value={amt} onChange={e => setAmt(e.target.value.replace(/[^\d.]/g, ""))} style={{ ...cellI, width: 130, fontFamily: mono, fontWeight: 600 }} />
            </div>
            <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 6 }}>In words: {amt ? wordsIN(Number(amt)) : "—"}</div>
          </div>

          {/* signature */}
          <SignBlock user={u} firm={activeFirm} when={stamp} />
        </div>

        {/* send controls */}
        <div style={{ marginBottom: 14 }}>
          <SendPanel
            email={email} setEmail={setEmail} wa={wa} setWa={setWa}
            chEmail={chEmail} setChEmail={setChEmail} chWa={chWa} setChWa={setChWa}
            subject={mailSubj} setSubject={setMailSubj}
            body={mailBody} setBody={setMailBody}
            attachment={`${claimId}.pdf`} />
        </div>
        <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
          <GoldButton onClick={send}><span style={{ display: "inline-flex", alignItems: "center", gap: 7 }}><Send size={14} /> Send to vendor</span></GoldButton>
          <GoldButton ghost onClick={() => printThis()}><span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Printer size={14} /> Print</span></GoldButton>
          <GoldButton ghost onClick={onClose}>Cancel</GoldButton>
        </div>
        <div style={{ display: "flex", alignItems: "flex-start", gap: 8, marginTop: 12, font: `11px ${sans}`, color: C.stone }}><Info size={13} color={C.goldDeep} style={{ flexShrink: 0, marginTop: 1 }} /> The letter, the signature and the claim log are real in the app. Actual email / WhatsApp delivery connects with the backend gateway.</div>
      </div>
    </Overlay>
  );
}

