function EvidenceRow({ ev, setEv }) {
  const add = (kind, name) => setEv(e => [...e, { kind, name, at: new Date().toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" }) }]);
  const btn = { ...softBtn, cursor: "pointer", display: "inline-flex", alignItems: "center", gap: 6, font: `600 11px ${sans}` };
  return (
    <div>
      <div style={{ display: "flex", gap: 7, flexWrap: "wrap" }}>
        <label style={btn}><Camera size={13} /> Photo<input type="file" accept="image/*" capture="environment" multiple onChange={e => [...e.target.files].forEach(f => add("Photo", f.name))} style={{ display: "none" }} /></label>
        <label style={btn}><Video size={13} /> Video<input type="file" accept="video/*" capture="environment" onChange={e => [...e.target.files].forEach(f => add("Video", f.name))} style={{ display: "none" }} /></label>
        <button onClick={() => add("Voice note", `voice-${Math.floor(Math.random() * 900 + 100)}.m4a`)} style={btn}><Mic size={13} /> Voice note</button>
      </div>
      {ev.length > 0 && (
        <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginTop: 8 }}>
          {ev.map((x, i) => (
            <span key={i} style={{ display: "inline-flex", alignItems: "center", gap: 5, background: C.goldTint, border: `1px solid ${C.goldSoft}`, borderRadius: 20, padding: "4px 9px", font: `11px ${sans}`, color: C.goldDeep }}>
              {x.kind === "Photo" ? <Camera size={11} /> : x.kind === "Video" ? <Video size={11} /> : <Mic size={11} />}
              {x.kind} · {x.at}
              <button onClick={() => setEv(e => e.filter((_, k) => k !== i))} style={{ background: "none", border: "none", cursor: "pointer", color: C.stone, padding: 0 }}><X size={11} /></button>
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

/* ===== GUIDED GATE CAPTURE — the app talks the guard through it ===== */
function GateAnimStyles() {
  return <style>{`
@keyframes mbWalk { 0%,100% { transform: translateX(0) } 50% { transform: translateX(6px) } }
@keyframes mbFlash { 0%,72%,100% { opacity: 0 } 78%,88% { opacity: 1 } }
@keyframes mbBeam { 0% { opacity: .15; transform: scaleX(.86) } 50% { opacity: .55; transform: scaleX(1) } 100% { opacity: .15; transform: scaleX(.86) } }
@keyframes mbFrame { 0%,100% { stroke-dashoffset: 0 } 100% { stroke-dashoffset: -40 } }
@keyframes mbBob { 0%,100% { transform: translateY(0) } 50% { transform: translateY(-3px) } }
@keyframes mbPulse { 0%,100% { box-shadow: 0 0 0 0 rgba(176,80,60,.55) } 50% { box-shadow: 0 0 0 7px rgba(176,80,60,0) } }
@keyframes mbPop { 0% { transform: scale(.6); opacity: 0 } 60% { transform: scale(1.12); opacity: 1 } 100% { transform: scale(1); opacity: 1 } }
`}</style>;
}
