/* the intake pipeline — what the app "eats" */
const INTAKE_SAMPLE = {
  zip: [
    { cat: "Interest paid", dept: "Accounts", amt: 962000, party: "HDFC · project facility", date: "05 Aug", conf: 96 },
    { cat: "Bank charges", dept: "Accounts", amt: 8450, party: "HDFC · NEFT charges", date: "05 Aug", conf: 94 },
    { cat: "Rent & utilities", dept: "Admin", amt: 285000, party: "Office rent — auto debit", date: "05 Aug", conf: 91 },
    { cat: "Material", dept: "Purchase", amt: 1560000, party: "UltraTech — matched to PO-4468", date: "10 Aug", conf: 98 },
    { cat: "", dept: "", amt: 47800, party: "IMPS to “S. TRADERS” — no match", date: "08 Aug", conf: 38 },
  ],
  pdf: [{ cat: "Material", dept: "Purchase", amt: 1560000, party: "UltraTech — Kharar · INV-8841", date: "10 Aug", conf: 97 }],
  photo: [{ cat: "Canteen & food", dept: "Site Engineering", amt: 128400, party: "Site canteen · Grand — July", date: "31 Jul", conf: 88 }],
  email: [{ cat: "Subscriptions", dept: "Accounts", amt: 42000, party: "Tally · annual renewal", date: "28 Jul", conf: 93 }],
};

function IntakeStyles() {
  return <style>{`
@keyframes mbScan{0%{top:0}50%{top:calc(100% - 3px)}100%{top:0}}
@keyframes mbFloat{0%,100%{transform:translateY(0) rotate(-2deg)}50%{transform:translateY(-7px) rotate(2deg)}}
@keyframes mbSpin{to{transform:rotate(360deg)}}
@keyframes mbPopIn{0%{opacity:0;transform:translateY(10px) scale(.96)}100%{opacity:1;transform:none}}
`}</style>;
}

function DocIntake({ onClose, onFiled }) {
  const mob = useIsMobile(); const { activeFirm } = useProc();
  const [stage, setStage] = useState("drop");   // drop → eating → review → done
  const [kind, setKind] = useState("pdf");
  const [fileName, setFileName] = useState("");
  const [step, setStep] = useState(0);          // 0 read → 1 understand → 2 draft
  const [rows, setRows] = useState([]);
  const STEPS = [["Reading it", "Turning the page into text — even a crooked photo."],
                 ["Understanding it", "Finding the amount, the date, the party and the tax."],
                 ["Drafting the entry", "Choosing the head of expense and the department."]];
  const cell = { ...inp, margin: 0, padding: "8px 10px", fontSize: 13, boxSizing: "border-box" };

  const eat = (k, name, count) => {
    setKind(k); setFileName(name); setStage("eating"); setStep(0);
    setTimeout(() => setStep(1), 1400);
    setTimeout(() => setStep(2), 2900);
    setTimeout(() => {
      const base = INTAKE_SAMPLE[k] || INTAKE_SAMPLE.pdf;
      let out = base.map((r, i) => ({ ...r, id: "DR-" + (700 + i + Math.floor(Math.random() * 90)), keep: true }));
      if (k === "zip") {
        const extra = [];
        for (let i = 0; i < (count || 37); i++) {
          const c = EXP_CATS[(i * 3) % EXP_CATS.length][0], d = EXP_DEPTS[(i * 5) % EXP_DEPTS.length];
          extra.push({ id: "DR-" + (800 + i), cat: c, dept: d, amt: 4000 + ((i * 7919) % 240000), party: `Statement line ${i + 1}`, date: "Aug", conf: 82 + (i % 16), keep: true, bulk: true });
        }
        out = out.concat(extra);
      }
      setRows(out); setStage("review");
    }, 4400);
  };
  const needEye = rows.filter(r => r.conf < 60);
  const good = rows.filter(r => r.conf >= 60);
  const file = () => {
    const kept = rows.filter(r => r.keep && r.cat);
    if (!kept.length) return toast("Nothing to file — set a head of expense first", "amber");
    onFiled && onFiled(kept); setStage("done");
  };

  if (stage === "done") return (
    <Overlay onClose={onClose} width={520}>
      <div style={{ padding: mob ? 20 : 26, textAlign: "center" }}>
        <div style={{ width: 42, height: 42, borderRadius: "50%", background: C.greenSoft, display: "grid", placeItems: "center", margin: "0 auto 12px" }}><Check size={22} color={C.green} /></div>
        <h2 style={{ font: `400 21px ${serif}`, margin: "0 0 6px" }}>Filed into the ledger</h2>
        <div style={{ font: `13px ${sans}`, color: C.stone, lineHeight: 1.6, marginBottom: 16 }}>
          {rows.filter(r => r.keep && r.cat).length} entries, sorted by head of expense and charged to the right department.
        </div>
        <GoldButton small onClick={onClose}>Done</GoldButton>
      </div>
    </Overlay>
  );

  return (
    <Overlay onClose={onClose} width={760}>
      <IntakeStyles />
      <div style={{ padding: mob ? 16 : 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
          <Upload size={18} color={C.gold} /><Eyebrow>Feed the ledger</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>

        {stage === "drop" && (<>
          <h2 style={{ font: `400 21px ${serif}`, margin: "4px 0 4px" }}>Give it anything.</h2>
          <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 14 }}>A bill, a scan, a photograph taken in a hurry, an email, a whole year of bank statements in a zip. It reads it, sorts it, and shows you the draft before anything is filed.</div>
          <div style={{ display: mob ? "block" : "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 10 }}>
            {[["pdf", "📄", "A bill or invoice", "PDF from the vendor"],
              ["photo", "📷", "A photograph", "Crooked, creased, taken at site"],
              ["email", "✉️", "An email receipt", "Subscriptions, renewals"],
              ["zip", "🗂️", "A zip of statements", "A whole year, all at once"]].map(([k, ic, t, s2]) => (
              <label key={k} style={{ display: "block", cursor: "pointer", background: C.paper, border: `1px solid ${C.line}`, borderRadius: 12, padding: 14, marginBottom: mob ? 9 : 0 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 11 }}>
                  <span style={{ fontSize: 25, animation: "mbFloat 3.4s ease-in-out infinite" }}>{ic}</span>
                  <div><div style={{ font: `600 13px ${sans}`, color: C.ink }}>{t}</div><div style={{ font: `11px ${sans}`, color: C.stone }}>{s2}</div></div>
                </div>
                <input type="file" multiple onChange={e => { const f = e.target.files[0]; eat(k, f ? f.name : (k === "zip" ? "statements-2026.zip" : "document"), e.target.files.length); }} style={{ display: "none" }} />
              </label>
            ))}
          </div>
          <div style={{ display: "flex", gap: 8, marginTop: 12, flexWrap: "wrap", alignItems: "center" }}>
            <GoldButton small ghost onClick={() => eat("zip", "HDFC-statements-Apr-Aug.zip", 37)}>Try it with a year of statements</GoldButton>
            <span style={{ font: `11px ${sans}`, color: C.stone }}>Nothing is filed until you say so.</span>
          </div>
        </>)}

        {stage === "eating" && (
          <div style={{ padding: "14px 0" }}>
            <h2 style={{ font: `400 20px ${serif}`, margin: "0 0 14px" }}>Reading {fileName}…</h2>
            <div style={{ display: "flex", gap: 16, alignItems: "center", flexWrap: "wrap" }}>
              <div style={{ position: "relative", width: 118, height: 148, background: "#fff", border: `1px solid ${C.line}`, borderRadius: 8, overflow: "hidden", flexShrink: 0, boxShadow: "0 14px 30px rgba(22,52,95,.18)" }}>
                {[18, 34, 50, 66, 82, 98, 114].map((y, i) => <div key={i} style={{ position: "absolute", left: 12, right: i % 3 === 0 ? 40 : 12, top: y, height: 5, background: C.lineSoft, borderRadius: 2 }} />)}
                <div style={{ position: "absolute", left: 0, right: 0, height: 3, background: C.gold, boxShadow: `0 0 14px ${C.gold}`, animation: "mbScan 1.5s ease-in-out infinite" }} />
              </div>
              <div style={{ flex: 1, minWidth: 200 }}>
                {STEPS.map(([t, s2], i) => (
                  <div key={i} style={{ display: "flex", alignItems: "flex-start", gap: 10, padding: "9px 0", opacity: i <= step ? 1 : 0.32, transition: "opacity .4s" }}>
                    <div style={{ width: 24, height: 24, borderRadius: "50%", flexShrink: 0, display: "grid", placeItems: "center", background: i < step ? C.greenSoft : i === step ? C.goldTint : "#fff", border: `1px solid ${i < step ? C.green : i === step ? C.gold : C.line}` }}>
                      {i < step ? <Check size={12} color={C.green} />
                        : i === step ? <div style={{ width: 11, height: 11, border: `2px solid ${C.gold}`, borderTopColor: "transparent", borderRadius: "50%", animation: "mbSpin .8s linear infinite" }} />
                        : <span style={{ font: `600 10px ${sans}`, color: C.stone }}>{i + 1}</span>}
                    </div>
                    <div><div style={{ font: `600 13px ${sans}`, color: C.ink }}>{t}</div><div style={{ font: `11px ${sans}`, color: C.stone }}>{s2}</div></div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {stage === "review" && (<>
          <h2 style={{ font: `400 21px ${serif}`, margin: "4px 0 4px" }}>Check the draft before it is filed.</h2>
          <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 12 }}>
            {rows.length} entries found in {fileName}. {needEye.length ? `${needEye.length} need your eye.` : "All of them look clean."} Nothing is in the books yet.
          </div>
          {needEye.length > 0 && (
            <div style={{ background: C.amberSoft, border: `1px solid ${C.amber}`, borderRadius: 10, padding: 11, marginBottom: 12, display: "flex", gap: 8, font: `12px ${sans}`, color: C.inkSoft }}>
              <TriangleAlert size={15} color={C.amber} style={{ flexShrink: 0 }} /><div>Some lines could not be matched to anything we know. Set the head of expense yourself, or leave them out.</div>
            </div>
          )}
          <div style={{ maxHeight: mob ? 300 : 340, overflowY: "auto", paddingRight: 4 }}>
            {rows.slice(0, 12).map((r, i) => (
              <div key={r.id} style={{ background: r.conf < 60 ? C.amberSoft : "#fff", border: `1px solid ${r.conf < 60 ? C.amber : C.line}`, borderRadius: 11, padding: 11, marginBottom: 8, animation: `mbPopIn .4s ${i * 0.05}s both` }}>
                <div style={{ display: "flex", alignItems: "center", gap: 9, flexWrap: "wrap" }}>
                  <input type="checkbox" checked={r.keep} onChange={e => setRows(a => a.map(x => x.id === r.id ? { ...x, keep: e.target.checked } : x))} />
                  <div style={{ flex: 1, minWidth: 150 }}>
                    <div style={{ font: `600 12px ${sans}`, color: C.ink }}>{r.party}</div>
                    <div style={{ font: `11px ${sans}`, color: C.stone }}>{r.date} · read at {r.conf}% certainty</div>
                  </div>
                  <span style={{ font: `13px ${mono}`, color: C.ink }}>{inr(r.amt)}</span>
                </div>
                <div style={{ display: "flex", gap: 7, marginTop: 8, flexWrap: "wrap" }}>
                  <select value={r.cat} onChange={e => setRows(a => a.map(x => x.id === r.id ? { ...x, cat: e.target.value } : x))} style={{ ...sel, margin: 0, width: mob ? "100%" : 190, padding: "7px 9px", fontSize: 12 }}>
                    <option value="">— pick the head of expense —</option>
                    {EXP_CATS.map(([c]) => <option key={c}>{c}</option>)}
                  </select>
                  <select value={r.dept} onChange={e => setRows(a => a.map(x => x.id === r.id ? { ...x, dept: e.target.value } : x))} style={{ ...sel, margin: 0, width: mob ? "100%" : 160, padding: "7px 9px", fontSize: 12 }}>
                    <option value="">— which department —</option>
                    {EXP_DEPTS.map(d => <option key={d}>{d}</option>)}
                  </select>
                </div>
              </div>
            ))}
            {rows.length > 12 && <div style={{ font: `12px ${sans}`, color: C.stone, textAlign: "center", padding: "8px 0" }}>+ {rows.length - 12} more read the same way, all set to be filed.</div>}
          </div>
          <div style={{ display: "flex", gap: 10, marginTop: 14, flexWrap: "wrap", alignItems: "center" }}>
            <GreenButton onClick={file}><span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Check size={14} /> File {rows.filter(r => r.keep && r.cat).length} entries</span></GreenButton>
            <GoldButton ghost onClick={() => setStage("drop")}>Feed something else</GoldButton>
          </div>
          <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 10 }}>Real reading of PDFs, scans, photographs and mailboxes is the backend engine. The sorting, the draft and this approval step are real.</div>
        </>)}
      </div>
    </Overlay>
  );
}

