function ReminderCompose({ s, m, onClose, onQueue }) {
  const mob = useIsMobile();
  const [body, setBody] = useState(REMINDER_TMPL(s, m));
  const [subj, setSubj] = useState(`Payment reminder — ${s.unit}, ${s.proj}`);
  const [when, setWhen] = useState("Tomorrow, 10:00 AM");
  const [chE, setChE] = useState(true); const [chW, setChW] = useState(true);
  const cell = { ...inp, margin: 0, padding: "9px 10px", fontSize: 13, boxSizing: "border-box" };
  return (
    <Overlay onClose={onClose} width={620}>
      <div style={{ padding: mob ? 18 : 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 6 }}>
          <Send size={17} color={C.gold} /><Eyebrow>Payment reminder</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>
        <h2 style={{ font: `400 20px ${serif}`, margin: "4px 0 4px" }}>To {s.buyer} · {inr(m.amt)}</h2>
        <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 12 }}>Nothing goes to a buyer without the Chairman's approval. This is queued, not sent.</div>
        <div style={{ display: mob ? "block" : "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 10 }}>
          <div><label style={{ ...lbl, fontSize: 9, display: "flex", alignItems: "center", gap: 6 }}><input type="checkbox" checked={chE} onChange={e => setChE(e.target.checked)} /> Email</label>
            <div style={{ ...cell, marginTop: 5, background: "#fff", color: C.inkSoft, marginBottom: mob ? 8 : 0 }}>{s.email}</div></div>
          <div><label style={{ ...lbl, fontSize: 9, display: "flex", alignItems: "center", gap: 6 }}><input type="checkbox" checked={chW} onChange={e => setChW(e.target.checked)} /> WhatsApp</label>
            <div style={{ ...cell, marginTop: 5, background: "#fff", color: C.inkSoft }}>{s.phone}</div></div>
        </div>
        <label style={{ ...lbl, fontSize: 9 }}>Send at</label>
        <select value={when} onChange={e => setWhen(e.target.value)} style={{ ...sel, margin: "5px 0 10px" }}>
          {["Tomorrow, 10:00 AM", "In 3 days, 10:00 AM", "On the 1st, 10:00 AM", "On the 7th, 10:00 AM"].map(w => <option key={w}>{w}</option>)}
        </select>
        <label style={{ ...lbl, fontSize: 9 }}>Subject</label>
        <input value={subj} onChange={e => setSubj(e.target.value)} style={{ ...cell, margin: "5px 0 10px", fontWeight: 600 }} />
        <label style={{ ...lbl, fontSize: 9 }}>Message</label>
        <textarea value={body} onChange={e => setBody(e.target.value)} rows={mob ? 9 : 12} style={{ ...cell, marginTop: 5, resize: "vertical", lineHeight: 1.6 }} />
        <div style={{ display: "flex", gap: 10, marginTop: 14, flexWrap: "wrap" }}>
          <GoldButton onClick={() => { if (!chE && !chW) return toast("Pick a channel", "amber"); onQueue({ sale: s.id, buyer: s.buyer, unit: s.unit, amt: m.amt, when, subj, body, ch: [chE && "Email", chW && "WhatsApp"].filter(Boolean).join(" + ") }); }}>
            <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><ShieldCheck size={14} /> Send for the Chairman's approval</span>
          </GoldButton>
          <GoldButton ghost onClick={onClose}>Cancel</GoldButton>
        </div>
        <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 10 }}>Once approved it goes out at the time set above. Real email and WhatsApp delivery come with the backend.</div>
      </div>
    </Overlay>
  );
}

