function DataStrength() {
  const mob = useIsMobile();
  const { holds } = useProc();
  const banksOk = BANKS_SEED.filter(b => !b.gaps.length).length;
  const items = [
    ["Bank statements", banksOk, BANKS_SEED.length, "every account, month by month"],
    ["Buyer contacts", SALES_SEED.filter(s => s.phone && s.email).length, SALES_SEED.length, "phone and email on file"],
    ["Payment plans", SALES_SEED.filter(s => PAY_PLANS[s.plan]).length, SALES_SEED.length, "signed plan attached to the sale"],
    ["Vendor invoices", 13, 16, "a bill against every goods-in"],
    ["Expense heads set", EXP_SEED.filter(e => e.cat).length, EXP_SEED.length, "nothing sitting unclassified"],
  ];
  const score = Math.round(items.reduce((a, i) => a + i[1] / i[2], 0) / items.length * 100);
  const weak = items.filter(i => i[1] < i[2]);
  return (
    <Card pad={mob ? 14 : 20} style={{ marginBottom: 16, borderColor: score >= 90 ? C.green : C.amber }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8, flexWrap: "wrap" }}>
        <TrendingUp size={16} color={C.goldDeep} /><span style={{ font: `600 13px ${sans}`, color: C.ink }}>Strength of what we hold</span>
        <Pill tone={score >= 90 ? "green" : "amber"}>{score}%</Pill>
        <span style={{ marginLeft: "auto", font: `11px ${sans}`, color: C.stone }}>checked continuously</span>
      </div>
      <div style={{ height: 9, background: C.lineSoft, borderRadius: 20, overflow: "hidden", marginBottom: 10 }}>
        <div style={{ width: `${score}%`, height: "100%", background: score >= 90 ? C.green : C.gold, transition: "width .6s" }} />
      </div>
      <div style={{ font: `12px ${sans}`, color: C.inkSoft, marginBottom: 10 }}>
        {weak.length ? <>The dashboards are only as good as this. <b style={{ color: C.amber }}>{weak.length} area{weak.length > 1 ? "s" : ""}</b> still short of what they need.</> : "Everything the dashboards depend on is on file."}
      </div>
      {items.map(([k, a, b2, why], i) => {
        const full = a >= b2;
        return (
          <div key={k} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 0", borderTop: i ? `1px solid ${C.lineSoft}` : `1px solid ${C.line}`, flexWrap: "wrap" }}>
            <div style={{ width: 22, height: 22, borderRadius: 6, flexShrink: 0, display: "grid", placeItems: "center", background: full ? C.greenSoft : C.amberSoft }}>
              {full ? <Check size={12} color={C.green} /> : <TriangleAlert size={12} color={C.amber} />}
            </div>
            <div style={{ flex: 1, minWidth: 140 }}>
              <div style={{ font: `600 12px ${sans}`, color: C.ink }}>{k}</div>
              <div style={{ font: `11px ${sans}`, color: C.stone }}>{why}</div>
            </div>
            <span style={{ font: `13px ${mono}`, color: full ? C.green : C.amber }}>{a}/{b2}</span>
          </div>
        );
      })}
      <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 10 }}>This score moves the moment a statement, a bill or a buyer's number is added. It is the honest state of our records.</div>
    </Card>
  );
}

