/* ---------- authorisation. Client-side only — see the note at the top. ---------- */
function AuthGate({ label = "Authorise", pass, setPass, onOk, disabled, hint }) {
  const [err, setErr] = useState("");
  const go = () => {
    if (!pass.trim()) { setErr("Enter the authorisation code."); return; }
    if (pass.trim().toLowerCase() !== "marbella") { setErr("That code isn't right. Ask the HR Head."); return; }
    setErr(""); onOk();
  };
  return (
    <div style={{ background: C.paper, borderRadius: 11, padding: 14, marginTop: 4 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
        <LockIcon size={15} color={C.goldDeep} />
        <div style={{ font: `600 12px ${sans}`, color: C.ink }}>Authorisation code</div>
        <span style={{ marginLeft: "auto", font: `10px ${sans}`, color: C.stone }}>default: marbella</span>
      </div>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        <input type="password" value={pass} onChange={e => { setPass(e.target.value); setErr(""); }}
          placeholder="Enter code"
          style={{ flex: 1, minWidth: 150, padding: "10px 12px", border: `1px solid ${err ? C.red : C.line}`, borderRadius: 9, font: `13px ${sans}`, outline: "none", color: C.ink, background: "#fff" }} />
        <GoldButton small onClick={go}>
          <span style={{ display: "inline-flex", alignItems: "center", gap: 6, opacity: disabled ? .5 : 1 }}><Printer size={14} /> {label}</span>
        </GoldButton>
      </div>
      {err && <div style={{ font: `12px ${sans}`, color: C.red, marginTop: 7, display: "flex", alignItems: "center", gap: 5 }}><TriangleAlert size={13} /> {err}</div>}
      {hint && !err && <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 7 }}>{hint}</div>}
      <div style={{ font: `10px ${sans}`, color: C.stone, marginTop: 8, display: "flex", alignItems: "flex-start", gap: 5, lineHeight: 1.5 }}>
        <Info size={12} color={C.goldDeep} style={{ flexShrink: 0, marginTop: 1 }} />
        The code is checked in the browser. It stops a colleague printing from your screen — it is not access control. Enforcement belongs on the printer's server.
      </div>
    </div>
  );
}

/* ---------- fast path: the old card came back ---------- */
function DamagedSwap({ p, ver, onClose, onIssue }) {
  const mob = useIsMobile();
  const { people } = useProc();
  const [reason, setReason] = useState("damaged");
  const [got, setGot] = useState(false);
  const [who, setWho] = useState("Simran Kaur");
  const [pass, setPass] = useState("");
  const staff = people.filter(x => x.dept === "HR" || x.dept === "Admin").map(x => x.name);
  const ready = got && who;
  return (
    <Overlay onClose={onClose} width={520}>
      <div style={{ padding: mob ? 16 : 22 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
          <RotateCcw size={18} color={C.green} /><Eyebrow color={C.green}>Straight swap</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>
        <h3 style={{ font: `400 20px ${serif}`, margin: "6px 0 4px", color: C.ink }}>{p.name} — replace a worn card</h3>
        <p style={{ font: `13px ${sans}`, color: C.inkSoft, margin: "0 0 16px", lineHeight: 1.55 }}>
          The old card is in your hand, so there is nothing to investigate. Three ticks and it goes to the printer.
        </p>

        <label style={lbl}>What's wrong with it</label>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", margin: "7px 0 16px" }}>
          {["damaged", "faded", "broken"].map(k => (
            <button key={k} onClick={() => setReason(k)} style={{ cursor: "pointer", border: `1px solid ${reason === k ? C.green : C.line}`,
              background: reason === k ? C.greenSoft : "#fff", color: reason === k ? C.green : C.inkSoft, borderRadius: 20, padding: "8px 13px", font: `600 12px ${sans}` }}>
              {REISSUE[k].label}
            </button>
          ))}
        </div>

        <button onClick={() => setGot(!got)} style={{ width: "100%", textAlign: "left", cursor: "pointer", border: `1px solid ${got ? C.green : C.line}`,
          background: got ? C.greenSoft : "#fff", borderRadius: 11, padding: "13px 15px", display: "flex", alignItems: "center", gap: 11, marginBottom: 10 }}>
          <span style={{ width: 22, height: 22, borderRadius: 6, border: `1.5px solid ${got ? C.green : C.line}`, background: got ? C.green : "#fff", display: "grid", placeItems: "center", flexShrink: 0 }}>
            {got && <Check size={14} color="#fff" />}
          </span>
          <span>
            <span style={{ display: "block", font: `600 13px ${sans}`, color: C.ink }}>Old card received and destroyed</span>
            <span style={{ display: "block", font: `11px ${sans}`, color: C.stone, marginTop: 2 }}>Cut through the chip and the QR in front of the holder.</span>
          </span>
        </button>

        <label style={lbl}>Received by</label>
        <select value={who} onChange={e => setWho(e.target.value)} style={{ ...inp, margin: "7px 0 14px" }}>
          {staff.map(n => <option key={n}>{n}</option>)}
        </select>

        <div style={{ background: C.goldTint, borderRadius: 10, padding: "11px 13px", font: `12px ${sans}`, color: C.inkSoft, marginBottom: 12, lineHeight: 1.55 }}>
          Card <b style={{ color: C.ink }}>v{ver}</b> will be cancelled and <b style={{ color: C.ink }}>v{ver + 1}</b> printed. The zones stay the same.
        </div>

        <AuthGate label="Send to printer" pass={pass} setPass={setPass} disabled={!ready}
          hint={ready ? null : "Tick the two boxes above first."}
          onOk={() => {
            if (!ready) { toast("Confirm the old card came back first", "amber"); return; }
            onIssue({ reason, recv: who, note: `${REISSUE[reason].label}. Old card v${ver} received and destroyed.` });
            onClose();
          }} />
      </div>
    </Overlay>
  );
}

/* ---------- slow path: the card is out there somewhere ---------- */
function ReprintFlow({ p, ver, onClose, onIssue }) {
  const mob = useIsMobile();
  const [step, setStep] = useState(1);
  const [reason, setReason] = useState("lost");
  const [circ, setCirc] = useState("");
  const [when, setWhen] = useState("");
  const [told, setTold] = useState("");
  const [fir, setFir] = useState("");
  const [ticks, setTicks] = useState([]);
  const [pass, setPass] = useState("");
  const toggle = (i) => setTicks(t => t.includes(i) ? t.filter(x => x !== i) : [...t, i]);
  const zones = zonesFor(p);
  const okStep1 = circ.trim().length >= 25 && when.trim() && told.trim() && (reason !== "stolen" || fir.trim());
  const okStep2 = ticks.length === UNDERTAKINGS.length;

  return (
    <Overlay onClose={onClose} width={560}>
      <div style={{ padding: mob ? 16 : 22 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 4 }}>
          <ShieldQuestion size={18} color={C.red} /><Eyebrow color={C.red}>Card unaccounted for</Eyebrow>
          <span style={{ marginLeft: "auto", font: `11px ${sans}`, color: C.stone }}>Step {step} of 3</span>
          <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>
        <div style={{ height: 4, background: C.lineSoft, borderRadius: 3, margin: "10px 0 16px" }}>
          <div style={{ width: `${(step / 3) * 100}%`, height: "100%", background: `linear-gradient(90deg, ${C.gold}, ${C.goldDeep})`, borderRadius: 3, transition: "width .25s" }} />
        </div>

        <div style={{ background: C.redSoft, border: `1px solid ${C.red}`, borderRadius: 11, padding: "12px 14px", marginBottom: 16 }}>
          <div style={{ display: "flex", gap: 9, alignItems: "flex-start" }}>
            <TriangleAlert size={16} color={C.red} style={{ flexShrink: 0, marginTop: 1 }} />
            <div style={{ font: `12px ${sans}`, color: "#7A3326", lineHeight: 1.6 }}>
              <b>{p.name}</b>'s card opens {zones.length} area{zones.length > 1 ? "s" : ""} — {zones.join(", ")}. Until it is cancelled, whoever holds it can walk into every one of them.
            </div>
          </div>
        </div>

        {step === 1 && (
          <>
            <label style={lbl}>What happened to it</label>
            <div style={{ display: "flex", gap: 8, flexWrap: "wrap", margin: "7px 0 16px" }}>
              {["lost", "stolen", "notreturn", "namechg"].map(k => (
                <button key={k} onClick={() => setReason(k)} style={{ cursor: "pointer", border: `1px solid ${reason === k ? C.red : C.line}`,
                  background: reason === k ? C.redSoft : "#fff", color: reason === k ? C.red : C.inkSoft, borderRadius: 20, padding: "8px 13px", font: `600 12px ${sans}` }}>
                  {REISSUE[k].label}
                </button>
              ))}
            </div>

            <Field label="When was it last definitely in hand?" hint="A date and roughly a time. Guesswork is fine, blanks are not."
              value={when} onChange={setWhen} placeholder="e.g. 2 Jul, around 4pm leaving site" />

            <Field label="What happened — in the holder's own words" area
              hint="Where they were, what they were doing, what they did to find it. This is the part that matters later."
              value={circ} onChange={setCirc} placeholder="Left it in a shared auto between Sector 22 and the site. Went back to the stand the same evening and called the driver — not found." />
            <div style={{ font: `11px ${sans}`, color: circ.trim().length >= 25 ? C.green : C.stone, marginTop: -8, marginBottom: 14 }}>
              {circ.trim().length >= 25 ? "That's enough to be useful." : `${circ.trim().length}/25 characters — a one-word answer is no answer.`}
            </div>

            <Field label="Who did they tell, and when?" hint="Reporting manager, security in-charge, anyone else."
              value={told} onChange={setTold} placeholder="R. Khanna, same evening by phone" />

            {reason === "stolen" && (
              <Field label="Police complaint / FIR number" hint="A stolen company access card should be reported. Enter the reference."
                value={fir} onChange={setFir} placeholder="e.g. DDR 214/2026, PS Sector 26" />
            )}

            <GoldButton onClick={() => okStep1 ? setStep(2) : toast("Fill in every field before moving on", "amber")}>
              <span style={{ display: "inline-flex", alignItems: "center", gap: 7, opacity: okStep1 ? 1 : .55 }}>Continue <ArrowRight size={14} /></span>
            </GoldButton>
          </>
        )}

        {step === 2 && (
          <>
            <div style={{ font: `600 13px ${sans}`, color: C.ink, marginBottom: 4 }}>Read to the holder, then tick each one</div>
            <div style={{ font: `12px ${sans}`, color: C.stone, marginBottom: 14 }}>All five. This is what they are agreeing to.</div>
            {UNDERTAKINGS.map((u, i) => {
              const on = ticks.includes(i);
              return (
                <button key={i} onClick={() => toggle(i)} style={{ width: "100%", textAlign: "left", cursor: "pointer",
                  border: `1px solid ${on ? C.green : C.line}`, background: on ? C.greenSoft : "#fff", borderRadius: 10,
                  padding: "12px 14px", display: "flex", alignItems: "flex-start", gap: 11, marginBottom: 8 }}>
                  <span style={{ width: 20, height: 20, borderRadius: 5, border: `1.5px solid ${on ? C.green : C.line}`, background: on ? C.green : "#fff", display: "grid", placeItems: "center", flexShrink: 0, marginTop: 1 }}>
                    {on && <Check size={13} color="#fff" />}
                  </span>
                  <span style={{ font: `12px ${sans}`, color: C.ink, lineHeight: 1.55 }}>{u}</span>
                </button>
              );
            })}
            <div style={{ display: "flex", gap: 8, marginTop: 14 }}>
              <button onClick={() => setStep(1)} style={softBtn}>Back</button>
              <div style={{ marginLeft: "auto" }}>
                <GoldButton onClick={() => okStep2 ? setStep(3) : toast("Every undertaking has to be ticked", "amber")}>
                  <span style={{ display: "inline-flex", alignItems: "center", gap: 7, opacity: okStep2 ? 1 : .55 }}>Continue <ArrowRight size={14} /></span>
                </GoldButton>
              </div>
            </div>
          </>
        )}

        {step === 3 && (
          <>
            <div style={{ background: C.paper, borderRadius: 11, padding: 14, marginBottom: 14 }}>
              <div style={{ font: `600 11px ${sans}`, letterSpacing: ".1em", textTransform: "uppercase", color: C.stone, marginBottom: 9 }}>What gets recorded</div>
              {[["Holder", `${p.name} · ${p.id}`], ["Reason", REISSUE[reason].label], ["Last in hand", when],
                ["Told", told], ...(reason === "stolen" ? [["FIR", fir]] : []), ["Undertakings", "All five agreed"],
                ["Old card", `v${ver} cancelled — access revoked at every gate`], ["New card", `v${ver + 1}`]].map(([k, v]) => (
                <div key={k} style={{ display: "flex", gap: 10, padding: "5px 0", font: `12px ${sans}` }}>
                  <span style={{ width: 110, color: C.stone, flexShrink: 0 }}>{k}</span>
                  <span style={{ color: C.ink, fontWeight: 600 }}>{v}</span>
                </div>
              ))}
              <div style={{ marginTop: 8, paddingTop: 8, borderTop: `1px solid ${C.line}`, font: `12px ${sans}`, color: C.inkSoft, fontStyle: "italic", lineHeight: 1.55 }}>"{circ}"</div>
            </div>
            <div style={{ display: "flex", alignItems: "flex-start", gap: 7, font: `11px ${sans}`, color: C.stone, marginBottom: 12, lineHeight: 1.5 }}>
              <History size={13} color={C.goldDeep} style={{ flexShrink: 0, marginTop: 1 }} />
              This entry can be added to but never edited or deleted. That is the point of it.
            </div>
            <AuthGate label="Cancel old card &amp; print new" pass={pass} setPass={setPass}
              onOk={() => {
                onIssue({ reason, recv: "—", killed: true,
                  note: `${REISSUE[reason].label}. Last in hand ${when}. Told ${told}.${reason === "stolen" ? ` FIR ${fir}.` : ""} ${circ}` });
                onClose();
              }} />
            <div style={{ marginTop: 10 }}><button onClick={() => setStep(2)} style={softBtn}>Back</button></div>
          </>
        )}
      </div>
    </Overlay>
  );
}

/* ---------- one person's card, its history, and the two doors ---------- */
function CardPersonView({ p, onBack }) {
  const mob = useIsMobile();
  const { cardLog, issueCard } = useProc();
  const [swap, setSwap] = useState(false);
  const [reprint, setReprint] = useState(false);
  const mine = cardLog.filter(c => c.pid === p.id);
  const ver = mine.length ? Math.max(...mine.map(c => c.ver)) : 0;
  const last = mine[0];
  const zones = zonesFor(p);

  return (
    <div>
      <button onClick={onBack} style={{ ...softBtn, marginBottom: 14, display: "inline-flex", alignItems: "center", gap: 6 }}><ArrowLeft size={14} /> All cards</button>

      <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr" : "320px 1fr", gap: 18, alignItems: "start" }}>
        <div>
          {ver > 0 ? <CardFace p={p} ver={ver} /> : (
            <div style={{ width: 300, height: 190, border: `1.5px dashed ${C.line}`, borderRadius: 14, display: "grid", placeItems: "center", background: C.paper, textAlign: "center", padding: 20 }}>
              <div>
                <ScanFace size={26} color={C.stone} />
                <div style={{ font: `600 13px ${sans}`, color: C.ink, marginTop: 8 }}>No card has ever been issued</div>
                <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 4 }}>This person has never held a Marbella ID.</div>
              </div>
            </div>
          )}
          <div style={{ display: "flex", gap: 8, marginTop: 14, flexWrap: "wrap" }}>
            {ver === 0
              ? <GoldButton small onClick={() => { issueCard(p, { reason: "first", recv: "—", note: "First issue." }); toast(`Card v1 queued for ${p.name}`, "green"); }}>
                  <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}><Printer size={14} /> Issue first card</span></GoldButton>
              : <>
                  <GreenButton small onClick={() => setSwap(true)}><RotateCcw size={14} /> Old card returned</GreenButton>
                  <button onClick={() => setReprint(true)} style={{ ...softBtn, borderColor: C.red, color: C.red, background: C.redSoft }}>Lost or stolen</button>
                </>}
          </div>
        </div>

        <div>
          <Eyebrow>Card holder</Eyebrow>
          <h2 style={{ font: `400 24px ${serif}`, margin: "6px 0 3px", color: C.ink }}>{p.name}</h2>
          <div style={{ font: `13px ${sans}`, color: C.inkSoft, marginBottom: 14 }}>{p.designation} · {p.dept} · <span style={{ font: `600 12px ${mono}`, color: C.goldDeep }}>{p.id}</span></div>

          <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr 1fr" : "repeat(4, 1fr)", gap: 10, marginBottom: 16 }}>
            {[["Current card", ver ? `v${ver}` : "none", ver ? C.ink : C.stone],
              ["Times issued", String(mine.length), C.ink],
              ["Last printed", last ? last.at.split(" · ")[0] : "—", C.ink],
              ["Zones open", String(zones.length), C.goldDeep]].map(([k, v, col]) => (
              <div key={k} style={{ background: C.paper, borderRadius: 10, padding: "11px 13px" }}>
                <div style={{ font: `600 10px ${sans}`, letterSpacing: ".08em", textTransform: "uppercase", color: C.stone }}>{k}</div>
                <div style={{ font: `600 16px ${sans}`, color: col, marginTop: 3 }}>{v}</div>
              </div>
            ))}
          </div>

          {mine.length >= 3 && (
            <div style={{ background: C.amberSoft, border: `1px solid ${C.amber}`, borderRadius: 10, padding: "11px 13px", marginBottom: 14, display: "flex", gap: 9, alignItems: "flex-start" }}>
              <TriangleAlert size={15} color={C.amber} style={{ flexShrink: 0, marginTop: 1 }} />
              <div style={{ font: `12px ${sans}`, color: "#6E4E12", lineHeight: 1.55 }}>
                This is card number {mine.length}. Three or more is a pattern worth a conversation, not another print job.
              </div>
            </div>
          )}

          <Card pad={16}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
              <History size={15} color={C.goldDeep} /><Eyebrow>Issue history</Eyebrow>
              <span style={{ marginLeft: "auto", font: `11px ${sans}`, color: C.stone }}>append-only</span>
            </div>
            {mine.length ? mine.map((c, i) => {
              const R = REISSUE[c.reason] || REISSUE.first;
              return (
                <div key={c.id} style={{ padding: "12px 0", borderTop: i ? `1px solid ${C.lineSoft}` : "none" }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                    <span style={{ font: `700 12px ${mono}`, color: C.ink }}>v{c.ver}</span>
                    <Pill tone={R.tone}>{R.label}</Pill>
                    <span style={{ font: `11px ${sans}`, color: C.stone }}>{c.at}</span>
                    <span style={{ marginLeft: "auto", font: `11px ${sans}`, color: C.stone }}>by {c.by}</span>
                  </div>
                  {c.note && <div style={{ font: `12px ${sans}`, color: C.inkSoft, marginTop: 5, lineHeight: 1.55 }}>{c.note}</div>}
                  <div style={{ display: "flex", gap: 12, marginTop: 5, flexWrap: "wrap", font: `11px ${sans}`, color: C.stone }}>
                    {c.recv && c.recv !== "—" && <span>Old card taken by {c.recv}</span>}
                    {c.killed && <span style={{ color: C.red }}>Previous card cancelled at all gates</span>}
                  </div>
                </div>
              );
            }) : <div style={{ font: `12px ${sans}`, color: C.stone, marginTop: 8 }}>Nothing yet.</div>}
          </Card>
        </div>
      </div>

      {swap && <DamagedSwap p={p} ver={ver} onClose={() => setSwap(false)} onIssue={(d) => { issueCard(p, d); toast(`Card v${ver + 1} sent to the printer`, "green"); }} />}
      {reprint && <ReprintFlow p={p} ver={ver} onClose={() => setReprint(false)} onIssue={(d) => { issueCard(p, d); toast(`Old card cancelled · v${ver + 1} queued`, "gold"); }} />}
    </div>
  );
}

/* ---------- the bureau: find a person, see what's been printed lately ---------- */
function CardBureauView() {
  const mob = useIsMobile();
  const { people, cardLog } = useProc();
  const [q, setQ] = useState("");
  const [open, setOpen] = useState(null);
  const hit = people.filter(p => {
    const s = q.trim().toLowerCase();
    if (!s) return false;
    return p.id.toLowerCase().includes(s) || p.name.toLowerCase().includes(s) || (p.designation || "").toLowerCase().includes(s);
  }).slice(0, 6);
  const exact = people.find(p => p.id.toLowerCase() === q.trim().toLowerCase());
  const person = open ? people.find(p => p.id === open) : null;
  const gone = open && !person;

  if (person) return <CardPersonView p={person} onBack={() => { setOpen(null); setQ(""); }} />;

  const flagged = people.filter(p => cardLog.filter(c => c.pid === p.id).length >= 2);

  return (
    <div>
      <div style={{ display: "flex", alignItems: "baseline", gap: 12, flexWrap: "wrap" }}>
        <Eyebrow>Card bureau</Eyebrow><Pill tone="gold">HR only</Pill>
      </div>
      <h1 style={{ font: `400 25px ${serif}`, margin: "6px 0 5px" }}>Issue and re-issue Marbella cards.</h1>
      <p style={{ font: `13px ${sans}`, color: C.inkSoft, maxWidth: 640, margin: "0 0 18px", lineHeight: 1.55 }}>
        Scan a card or type an Employee ID. A card opens doors — a straight swap takes seconds, a lost one takes a proper record.
      </p>

      <Card pad={mob ? 16 : 20} style={{ marginBottom: 18 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, border: `1.5px solid ${C.gold}`, borderRadius: 12, padding: "12px 15px", background: C.goldTint }}>
          <ScanLine size={19} color={C.goldDeep} />
          <input autoFocus value={q} onChange={e => setQ(e.target.value)}
            onKeyDown={e => { if (e.key === "Enter" && (exact || hit[0])) setOpen((exact || hit[0]).id); }}
            placeholder="Scan the QR, or type an ID or a name — e.g. MB-SEC-0001"
            style={{ border: "none", outline: "none", background: "transparent", flex: 1, font: `14px ${sans}`, color: C.ink }} />
          {q && <button onClick={() => setQ("")} style={{ background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={16} /></button>}
        </div>
        {hit.length > 0 && (
          <div style={{ marginTop: 10 }}>
            {hit.map(p => {
              const n = cardLog.filter(c => c.pid === p.id).length;
              return (
                <button key={p.id} onClick={() => setOpen(p.id)} style={{ width: "100%", textAlign: "left", cursor: "pointer", border: "none",
                  background: "#fff", borderRadius: 10, padding: "11px 13px", display: "flex", alignItems: "center", gap: 12, marginBottom: 6, boxShadow: "0 1px 0 rgba(22,52,95,.04)" }}>
                  <span style={{ width: 34, height: 34, borderRadius: 9, background: C.goldTint, display: "grid", placeItems: "center", color: C.goldDeep, font: `700 14px ${serif}`, flexShrink: 0 }}>{p.name[0]}</span>
                  <span style={{ flex: 1, minWidth: 0 }}>
                    <span style={{ display: "block", font: `600 13px ${sans}`, color: C.ink }}>{p.name}</span>
                    <span style={{ display: "block", font: `11px ${sans}`, color: C.stone }}>{p.designation} · {p.id}</span>
                  </span>
                  <Pill tone={n ? "stone" : "gold"}>{n ? `card v${n}` : "never issued"}</Pill>
                  <ChevronRight size={16} color={C.stone} />
                </button>
              );
            })}
          </div>
        )}
        {q.trim() && !hit.length && <div style={{ font: `12px ${sans}`, color: C.stone, marginTop: 12 }}>Nobody matches that. Check the ID.</div>}
        {gone && (
          <div style={{ marginTop: 12, background: C.amberSoft, border: `1px solid ${C.amber}`, borderRadius: 10, padding: "11px 13px", display: "flex", gap: 9, alignItems: "flex-start" }}>
            <TriangleAlert size={15} color={C.amber} style={{ flexShrink: 0, marginTop: 1 }} />
            <div style={{ font: `12px ${sans}`, color: "#6E4E12", lineHeight: 1.55, flex: 1 }}>
              <b>{open}</b> has a card on record but is no longer on the roster \u2014 they have left, or the ID was changed.
              Their card should be cancelled if it was never handed back.
            </div>
            <button onClick={() => setOpen(null)} style={{ background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={15} /></button>
          </div>
        )}
      </Card>

      <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr" : "1.4fr 1fr", gap: 16 }}>
        <Card pad={mob ? 14 : 18}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
            <Printer size={15} color={C.goldDeep} /><Eyebrow>Recently printed</Eyebrow>
            <span style={{ marginLeft: "auto", font: `11px ${sans}`, color: C.stone }}>{cardLog.length} on record</span>
          </div>
          {cardLog.slice(0, 8).map((c, i) => {
            const R = REISSUE[c.reason] || REISSUE.first;
            return (
              <button key={c.id} onClick={() => setOpen(c.pid)} style={{ width: "100%", textAlign: "left", cursor: "pointer", border: "none", background: "transparent",
                padding: "11px 0", borderTop: i ? `1px solid ${C.lineSoft}` : "none", display: "flex", alignItems: "center", gap: 10 }}>
                <span style={{ font: `700 11px ${mono}`, color: C.stone, width: 26 }}>v{c.ver}</span>
                <span style={{ flex: 1, minWidth: 0 }}>
                  <span style={{ display: "block", font: `600 13px ${sans}`, color: C.ink }}>{c.name}</span>
                  <span style={{ display: "block", font: `11px ${sans}`, color: C.stone }}>{c.at} · {c.by}</span>
                </span>
                <Pill tone={R.tone}>{R.label}</Pill>
              </button>
            );
          })}
        </Card>

        <Card pad={mob ? 14 : 18}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
            <TriangleAlert size={15} color={C.amber} /><Eyebrow color={C.amber}>Worth a look</Eyebrow>
          </div>
          <div style={{ font: `12px ${sans}`, color: C.inkSoft, margin: "7px 0 10px", lineHeight: 1.55 }}>
            People on their second card or beyond. Not an accusation — just a number worth knowing.
          </div>
          {flagged.length ? flagged.map(p => {
            const n = cardLog.filter(c => c.pid === p.id).length;
            return (
              <button key={p.id} onClick={() => setOpen(p.id)} style={{ width: "100%", textAlign: "left", cursor: "pointer", border: "none", background: "transparent",
                padding: "9px 0", display: "flex", alignItems: "center", gap: 10 }}>
                <span style={{ flex: 1, font: `600 13px ${sans}`, color: C.ink }}>{p.name}</span>
                <Pill tone={n >= 3 ? "red" : "amber"}>{n} cards</Pill>
              </button>
            );
          }) : <div style={{ font: `12px ${sans}`, color: C.stone }}>Nobody yet. Good.</div>}
        </Card>
      </div>
    </div>
  );
}

/* ---------- the org, drawn ---------- */
function OrgNode({ p, all, depth, expanded, toggle }) {
  const kids = all.filter(x => x.reportsTo === p.id && x.id !== p.id);
  const open = expanded.includes(p.id);
  const office = officeById(p.office);
  const count = (() => {
    const seen = new Set();
    const walk = (id) => all.filter(x => x.reportsTo === id && x.id !== id).forEach(c => { if (!seen.has(c.id)) { seen.add(c.id); walk(c.id); } });
    walk(p.id); return seen.size;
  })();
  return (
    <div style={{ marginLeft: depth ? 22 : 0, borderLeft: depth ? `1.5px solid ${C.line}` : "none", paddingLeft: depth ? 14 : 0, marginTop: 8 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, background: "#fff", border: `1px solid ${C.line}`,
        borderLeft: `4px solid ${office.tint}`, borderRadius: 10, padding: "10px 13px" }}>
        <span style={{ width: 32, height: 32, borderRadius: 9, background: office.tint, color: "#fff", display: "grid", placeItems: "center", font: `700 13px ${serif}`, flexShrink: 0 }}>{p.name[0]}</span>
        <span style={{ flex: 1, minWidth: 0 }}>
          <span style={{ display: "block", font: `600 13px ${sans}`, color: C.ink }}>{p.name}</span>
          <span style={{ display: "block", font: `11px ${sans}`, color: C.stone }}>{p.designation} · {office.short}</span>
        </span>
        {count > 0 && <Pill tone="gold">{count} under</Pill>}
        {kids.length > 0 && (
          <button onClick={() => toggle(p.id)} style={{ background: "none", border: "none", cursor: "pointer", color: C.stone, display: "grid", placeItems: "center" }}>
            <ChevronRight size={17} style={{ transform: open ? "rotate(90deg)" : "none", transition: "transform .18s" }} />
          </button>
        )}
      </div>
      {open && kids.map(k => <OrgNode key={k.id} p={k} all={all} depth={depth + 1} expanded={expanded} toggle={toggle} />)}
    </div>
  );
}

/* ---------- population: who, where, since when ---------- */
function PopulationView() {
  const mob = useIsMobile();
  const { people, deptRules, companies, projects, scope } = useProc();
  const [office, setOffice] = useState("all");
  const [dept, setDept] = useState("all");
  const [q, setQ] = useState("");
  const coName = (id) => (companies.find(c => c.id === id) || {}).name || "—";

  const inScope = (p) => scope === "group" || p.office === scope;
  const active = people.filter(p => p.status === "active" && inScope(p));
  const rows = active.filter(p =>
    (office === "all" || p.office === office) &&
    (dept === "all" || p.dept === dept) &&
    (!q.trim() || (p.name + p.id + p.designation).toLowerCase().includes(q.trim().toLowerCase()))
  );
  const byOffice = OFFICES.filter(o => scope === "group" || o.id === scope).map(o => ({ ...o, n: active.filter(p => p.office === o.id).length }));
  const depts = [...new Set(active.map(p => p.dept))].sort();

  return (
    <div>
      <div style={{ display: "flex", alignItems: "baseline", gap: 12, flexWrap: "wrap" }}>
        <Eyebrow>Population</Eyebrow><Pill tone="stone">{active.length} on the rolls</Pill>
      </div>
      <h1 style={{ font: `400 25px ${serif}`, margin: "6px 0 14px" }}>Everyone, and who employs them.</h1>
      <ScopeBar />

      <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr 1fr" : `repeat(${Math.max(1, byOffice.length)}, 1fr)`, gap: 10, marginBottom: 16 }}>
        {byOffice.map(o => (
          <button key={o.id} onClick={() => setOffice(office === o.id ? "all" : o.id)} style={{ cursor: "pointer", textAlign: "left",
            border: `1.5px solid ${office === o.id ? o.tint : C.line}`, background: office === o.id ? "#fff" : C.panel,
            borderRadius: 12, padding: "12px 14px", boxShadow: office === o.id ? `0 4px 14px ${o.tint}22` : "none" }}>
            <div style={{ width: 26, height: 5, borderRadius: 3, background: o.tint, marginBottom: 9 }} />
            <div style={{ font: `700 20px ${mono}`, color: C.ink }}>{o.n}</div>
            <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 2 }}>{o.short}</div>
          </button>
        ))}
      </div>

      <Card pad={mob ? 14 : 18} style={{ marginBottom: 16 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
          <Building2 size={15} color={C.gold} /><Eyebrow>On whose payroll</Eyebrow>
          <span style={{ marginLeft: "auto", font: `11px ${sans}`, color: C.stone }}>{active.length} in view</span>
        </div>
        {companies.map(c => {
          const n = active.filter(p => p.employer === c.id).length;
          if (!n) return null;
          return (
            <div key={c.id} style={{ padding: "8px 0" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <span style={{ flex: 1, font: `600 13px ${sans}`, color: C.ink }}>{c.name}</span>
                <span style={{ font: `11px ${mono}`, color: c.gstin ? C.stone : C.red }}>{c.gstin || "no GSTIN"}</span>
                <span style={{ font: `700 15px ${mono}`, color: C.ink, width: 34, textAlign: "right" }}>{n}</span>
              </div>
              <div style={{ height: 5, background: C.lineSoft, borderRadius: 3, marginTop: 5, overflow: "hidden" }}>
                <div style={{ width: `${(n / Math.max(1, active.length)) * 100}%`, height: "100%", background: C.gold }} />
              </div>
            </div>
          );
        })}
      </Card>

      <Card pad={mob ? 14 : 18}>
        <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center", marginBottom: 12 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, border: `1px solid ${C.line}`, borderRadius: 10, padding: "9px 12px", flex: 1, minWidth: 180, background: "#fff" }}>
            <Search size={15} color={C.stone} />
            <input value={q} onChange={e => setQ(e.target.value)} placeholder="Name, ID or designation"
              style={{ border: "none", outline: "none", flex: 1, font: `13px ${sans}`, color: C.ink, background: "transparent" }} />
          </div>
          <select value={dept} onChange={e => setDept(e.target.value)} style={{ ...inp, margin: 0, width: "auto", minWidth: 150 }}>
            <option value="all">All departments</option>
            {depts.map(d => <option key={d} value={d}>{d}</option>)}
          </select>
          {(office !== "all" || dept !== "all" || q) &&
            <button onClick={() => { setOffice("all"); setDept("all"); setQ(""); }} style={softBtn}>Clear</button>}
        </div>

        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", minWidth: 740 }}>
            <thead>
              <tr>{["Name", "Employee ID", "Designation", "Employed by", "Posted at", "Joined", "Day"].map(h => (
                <th key={h} style={{ textAlign: "left", font: `600 10px ${sans}`, letterSpacing: ".1em", textTransform: "uppercase",
                  color: C.stone, padding: "0 10px 9px 0", borderBottom: `1px solid ${C.line}` }}>{h}</th>
              ))}</tr>
            </thead>
            <tbody>
              {rows.map(p => {
                const o = officeById(p.office);
                const r = deptRules[p.dept];
                return (
                  <tr key={p.id}>
                    <td style={{ padding: "10px 10px 10px 0", borderBottom: `1px solid ${C.lineSoft}`, font: `600 13px ${sans}`, color: C.ink }}>{p.name}</td>
                    <td style={{ padding: "10px 10px 10px 0", borderBottom: `1px solid ${C.lineSoft}`, font: `12px ${mono}`, color: C.goldDeep }}>{p.id}</td>
                    <td style={{ padding: "10px 10px 10px 0", borderBottom: `1px solid ${C.lineSoft}`, font: `12px ${sans}`, color: C.ink }}>{p.designation}</td>
                    <td style={{ padding: "10px 10px 10px 0", borderBottom: `1px solid ${C.lineSoft}`, font: `12px ${sans}`, color: C.ink }}>{coName(p.employer)}</td>
                    <td style={{ padding: "10px 10px 10px 0", borderBottom: `1px solid ${C.lineSoft}` }}>
                      <span style={{ display: "inline-flex", alignItems: "center", gap: 6, font: `12px ${sans}`, color: C.inkSoft }}>
                        <span style={{ width: 8, height: 8, borderRadius: "50%", background: o.tint }} />{o.short}
                        <span style={{ color: C.stone }}>· {p.dept}</span>
                      </span>
                    </td>
                    <td style={{ padding: "10px 10px 10px 0", borderBottom: `1px solid ${C.lineSoft}`, font: `12px ${sans}`, color: C.stone }}>{p.joined}</td>
                    <td style={{ padding: "10px 0", borderBottom: `1px solid ${C.lineSoft}`, font: `12px ${mono}`, color: C.inkSoft }}>{r ? `${r.in}–${r.out}` : "—"}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          {!rows.length && <div style={{ font: `13px ${sans}`, color: C.stone, padding: "18px 0", textAlign: "center" }}>Nobody matches those filters.</div>}
        </div>
      </Card>
    </div>
  );
}

/* ---------- each department's day, as its manager defined it ---------- */
