/* ---------- a field that tells you what's wrong while you type ---------- */
function CheckedField({ label, hint, value, onChange, placeholder, check, mono: useMono }) {
  const r = check ? check(value) : { level: "none" };
  const col = r.level === "error" ? C.red : r.level === "warn" ? C.amber : r.level === "ok" ? C.green : C.line;
  return (
    <div style={{ marginBottom: 14 }}>
      <label style={lbl}>{label}</label>
      {hint && <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 3 }}>{hint}</div>}
      <input value={value} onChange={e => onChange(e.target.value.toUpperCase())} placeholder={placeholder}
        style={{ ...inp, margin: "7px 0 0", borderColor: col, fontFamily: useMono ? mono : sans, letterSpacing: useMono ? ".04em" : "normal" }} />
      {r.level !== "none" && r.msg && (
        <div style={{ display: "flex", gap: 6, alignItems: "flex-start", marginTop: 6, font: `11px ${sans}`,
          color: r.level === "error" ? C.red : r.level === "warn" ? C.amber : C.green, lineHeight: 1.5 }}>
          {r.level === "ok" ? <Check size={13} style={{ flexShrink: 0, marginTop: 1 }} /> : <TriangleAlert size={13} style={{ flexShrink: 0, marginTop: 1 }} />}
          <span>{r.msg}</span>
        </div>
      )}
    </div>
  );
}

/* ---------- add or edit a project ---------- */
function ProjectEditor({ existing, onClose }) {
  const mob = useIsMobile();
  const { companies, saveProject } = useProc();
  const [f, setF] = useState(existing || { name: "", short: "", company: companies[0].id, reraStatus: "notyet", rera: "", stage: "pre", addr: "" });
  const set = (k, v) => setF(s => ({ ...s, [k]: v }));
  const co = companies.find(c => c.id === f.company);
  const rr = reraCheck(f.rera, f.reraStatus);
  const save = () => {
    if (!f.name.trim()) { toast("The project needs a name", "amber"); return; }
    if (!f.company) { toast("Pick the company that owns it", "amber"); return; }
    if (rr.level === "error") { toast("RERA is marked received but the number is blank", "amber"); return; }
    saveProject({ ...f, id: f.id || f.name.toLowerCase().replace(/[^a-z0-9]+/g, "").slice(0, 10), short: f.short.trim() || f.name.trim().split(" ").slice(-1)[0] });
    toast(existing ? `${f.name} updated` : `${f.name} added`, "green");
    onClose();
  };
  return (
    <Overlay onClose={onClose} width={540}>
      <div style={{ padding: mob ? 16 : 22 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
          <HardHat size={18} color={C.gold} /><Eyebrow>{existing ? "Edit project" : "New project"}</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr" : "2fr 1fr", gap: 12 }}>
          <Field label="Project name" hint="As it's advertised." value={f.name} onChange={v => set("name", v)} placeholder="e.g. Marbella Manifest" />
          <Field label="Short name" hint="For the switcher." value={f.short} onChange={v => set("short", v)} placeholder="Manifest" />
        </div>

        <label style={lbl}>Company that owns it</label>
        <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 3 }}>This is the legal entity — the one that signs, pays and appears on the letterhead.</div>
        <select value={f.company} onChange={e => set("company", e.target.value)} style={{ ...inp, margin: "7px 0 6px" }}>
          {companies.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
        </select>
        {co && (
          <div style={{ background: C.paper, borderRadius: 9, padding: "10px 12px", marginBottom: 14, font: `12px ${sans}`, color: C.inkSoft, lineHeight: 1.6 }}>
            <div><b style={{ color: C.ink }}>{co.kind}</b> · GSTIN {co.gstin || <span style={{ color: C.red }}>not entered</span>}</div>
            <div style={{ marginTop: 2 }}>{co.addr}</div>
          </div>
        )}

        <label style={lbl}>RERA</label>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", margin: "7px 0 10px" }}>
          {Object.entries(RERA_STATUS).map(([k, v]) => {
            const on = f.reraStatus === k;
            const col = v.tone === "green" ? C.green : v.tone === "amber" ? C.amber : v.tone === "red" ? C.red : C.stone;
            return (
              <button key={k} onClick={() => set("reraStatus", k)} style={{ cursor: "pointer", border: `1px solid ${on ? col : C.line}`,
                background: on ? (v.tone === "green" ? C.greenSoft : v.tone === "amber" ? C.amberSoft : v.tone === "red" ? C.redSoft : C.lineSoft) : "#fff",
                color: on ? col : C.inkSoft, borderRadius: 20, padding: "8px 13px", font: `600 12px ${sans}` }}>{v.label}</button>
            );
          })}
        </div>
        <div style={{ font: `11px ${sans}`, color: C.stone, marginBottom: 12 }}>{RERA_STATUS[f.reraStatus].blurb}</div>
        {f.reraStatus === "received" && (
          <CheckedField label="RERA registration number" mono value={f.rera} onChange={v => set("rera", v)}
            placeholder="PBRERA-SAS79-PR0421" check={(v) => reraCheck(v, "received")} />
        )}

        <label style={lbl}>Stage</label>
        <div style={{ display: "flex", gap: 8, margin: "7px 0 14px", flexWrap: "wrap" }}>
          {[["pre", "Pre-construction"], ["building", "Under construction"], ["done", "Completed"]].map(([k, t]) => (
            <button key={k} onClick={() => set("stage", k)} style={{ cursor: "pointer", border: `1px solid ${f.stage === k ? C.gold : C.line}`,
              background: f.stage === k ? C.goldTint : "#fff", color: f.stage === k ? C.goldDeep : C.inkSoft, borderRadius: 20, padding: "8px 13px", font: `600 12px ${sans}` }}>{t}</button>
          ))}
        </div>

        <Field label="Site address" area hint="What goes on the gate pass and the delivery challan." value={f.addr} onChange={v => set("addr", v)} placeholder="Sector, road, district, PIN" />
        <GoldButton onClick={save}>{existing ? "Save changes" : "Add this project"}</GoldButton>
      </div>
    </Overlay>
  );
}

/* ---------- add or edit a company ---------- */
function CompanyEditor({ existing, onClose }) {
  const mob = useIsMobile();
  const { saveCompany } = useProc();
  const [f, setF] = useState(existing || { name: "", kind: "Partnership", gstin: "", pan: "", addr: "" });
  const set = (k, v) => setF(s => ({ ...s, [k]: v }));
  const g = gstinCheck(f.gstin);
  const save = () => {
    if (!f.name.trim()) { toast("The company needs its legal name", "amber"); return; }
    if (g.level === "error") { toast("Fix the GSTIN shape, or leave it blank for now", "amber"); return; }
    saveCompany({ ...f, id: f.id || f.name.toLowerCase().replace(/[^a-z0-9]+/g, "").slice(0, 10), pan: f.pan || (g.pan || "") });
    toast(existing ? `${f.name} updated` : `${f.name} added`, "green");
    onClose();
  };
  return (
    <Overlay onClose={onClose} width={520}>
      <div style={{ padding: mob ? 16 : 22 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
          <Building2 size={18} color={C.gold} /><Eyebrow>{existing ? "Edit company" : "New company"}</Eyebrow>
          <button onClick={onClose} style={{ marginLeft: "auto", background: "none", border: "none", cursor: "pointer", color: C.stone }}><X size={18} /></button>
        </div>
        <Field label="Legal name" hint="Exactly as on the GST certificate — this is what prints on the offer and relieving letters."
          value={f.name} onChange={v => set("name", v)} placeholder="e.g. SRG Developers and Promoters" />
        <label style={lbl}>Constitution</label>
        <select value={f.kind} onChange={e => set("kind", e.target.value)} style={{ ...inp, margin: "7px 0 14px" }}>
          {["Proprietorship", "Partnership", "LLP", "Private Limited", "Limited"].map(k => <option key={k}>{k}</option>)}
        </select>
        <CheckedField label="GSTIN" mono hint="Leave blank if it isn't registered yet." value={f.gstin} onChange={v => set("gstin", v)}
          placeholder="03AAEFD4921K1Z9" check={gstinCheck} />
        {g.level === "ok" || g.level === "warn" ? (
          <div style={{ background: C.paper, borderRadius: 9, padding: "9px 11px", marginTop: -6, marginBottom: 14, font: `11px ${sans}`, color: C.inkSoft }}>
            PAN is read straight out of the GSTIN: <b style={{ color: C.ink, fontFamily: mono }}>{g.pan}</b>
          </div>
        ) : null}
        <Field label="Registered address" area value={f.addr} onChange={v => set("addr", v)} placeholder="SCO 2417-18, Sector 22-C, Chandigarh 160022" />
        <GoldButton onClick={save}>{existing ? "Save changes" : "Add this company"}</GoldButton>
      </div>
    </Overlay>
  );
}

/* ---------- the register ---------- */
function CompaniesView() {
  const mob = useIsMobile();
  const { companies, projects, people, scope, setScope } = useProc();
  const [pEdit, setPEdit] = useState(null);
  const [cEdit, setCEdit] = useState(null);
  const [newP, setNewP] = useState(false);
  const [newC, setNewC] = useState(false);
  const active = people.filter(p => p.status === "active");
  const headOf = (cid) => active.filter(p => p.employer === cid).length;

  return (
    <div>
      <div style={{ display: "flex", alignItems: "baseline", gap: 12, flexWrap: "wrap" }}>
        <Eyebrow>Companies &amp; projects</Eyebrow><Pill tone="stone">{companies.length} companies · {projects.length} projects</Pill>
      </div>
      <h1 style={{ font: `400 25px ${serif}`, margin: "6px 0 5px" }}>Who owns what, and who employs whom.</h1>
      <p style={{ font: `13px ${sans}`, color: C.inkSoft, maxWidth: 680, margin: "0 0 18px", lineHeight: 1.55 }}>
        A project is a place. A company is the entity that signs the contract and pays the salary. Someone posted to
        Grand is employed by the LLP behind it — not by "Grand". That distinction decides whose letterhead their
        relieving letter carries.
      </p>

      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 18 }}>
        <GoldButton onClick={() => setNewP(true)}><span style={{ display: "inline-flex", alignItems: "center", gap: 7 }}><Plus size={15} /> New project</span></GoldButton>
        <GoldButton ghost onClick={() => setNewC(true)}><span style={{ display: "inline-flex", alignItems: "center", gap: 7 }}><Building2 size={15} /> New company</span></GoldButton>
      </div>

      {companies.map(co => {
        const mine = projects.filter(p => p.company === co.id);
        const g = gstinCheck(co.gstin);
        const n = headOf(co.id);
        return (
          <Card key={co.id} pad={mob ? 14 : 18} style={{ marginBottom: 14 }}>
            <div style={{ display: "flex", alignItems: "flex-start", gap: 12, flexWrap: "wrap", marginBottom: 12 }}>
              <div style={{ width: 40, height: 40, borderRadius: 11, background: C.ink, color: "#fff", display: "grid", placeItems: "center", flexShrink: 0 }}><Building2 size={19} /></div>
              <div style={{ flex: 1, minWidth: 180 }}>
                <div style={{ font: `600 15px ${sans}`, color: C.ink }}>{co.name}</div>
                <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center", marginTop: 5 }}>
                  <Pill tone="stone">{co.kind}</Pill>
                  <Pill tone={n ? "gold" : "stone"}>{n} on payroll</Pill>
                  <Pill tone="stone">{mine.length} {mine.length === 1 ? "project" : "projects"}</Pill>
                </div>
              </div>
              <button onClick={() => setCEdit(co)} style={{ ...softBtn, padding: "6px 12px" }}>Edit</button>
            </div>

            <div style={{ background: C.paper, borderRadius: 10, padding: "11px 13px", marginBottom: 12 }}>
              <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center" }}>
                <span style={{ font: `600 10px ${sans}`, letterSpacing: ".1em", textTransform: "uppercase", color: C.stone }}>GSTIN</span>
                <span style={{ font: `600 13px ${mono}`, color: co.gstin ? C.ink : C.red }}>{co.gstin || "not entered"}</span>
                {co.gstin && <Pill tone={g.level === "ok" ? "green" : g.level === "warn" ? "amber" : "red"}>
                  {g.level === "ok" ? "checks out" : g.level === "warn" ? "needs confirming" : "malformed"}
                </Pill>}
              </div>
              {co.gstin && g.msg && <div style={{ font: `11px ${sans}`, color: g.level === "ok" ? C.green : C.amber, marginTop: 6, lineHeight: 1.5 }}>{g.msg}</div>}
              <div style={{ font: `11px ${sans}`, color: C.stone, marginTop: 6 }}>{co.addr}</div>
            </div>

            {mine.map(pr => {
              const rs = RERA_STATUS[pr.reraStatus];
              return (
                <div key={pr.id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "11px 0", borderTop: `1px solid ${C.lineSoft}`, flexWrap: "wrap" }}>
                  <span style={{ width: 8, height: 8, borderRadius: "50%", background: pr.stage === "building" ? C.green : pr.stage === "pre" ? C.amber : C.stone, flexShrink: 0 }} />
                  <span style={{ flex: 1, minWidth: 150 }}>
                    <span style={{ display: "block", font: `600 13px ${sans}`, color: C.ink }}>{pr.name}</span>
                    <span style={{ display: "block", font: `11px ${mono}`, color: pr.reraStatus === "received" ? C.goldDeep : C.stone, marginTop: 2 }}>
                      {pr.reraStatus === "received" ? pr.rera : rs.label}
                    </span>
                  </span>
                  <Pill tone={rs.tone}>RERA · {rs.label}</Pill>
                  <button onClick={() => setPEdit(pr)} style={{ ...softBtn, padding: "5px 11px" }}>Edit</button>
                </div>
              );
            })}
            {!mine.length && <div style={{ font: `12px ${sans}`, color: C.stone, paddingTop: 10, borderTop: `1px solid ${C.lineSoft}` }}>No projects under this company yet.</div>}
          </Card>
        );
      })}

      {newP && <ProjectEditor onClose={() => setNewP(false)} />}
      {newC && <CompanyEditor onClose={() => setNewC(false)} />}
      {pEdit && <ProjectEditor existing={pEdit} onClose={() => setPEdit(null)} />}
      {cEdit && <CompanyEditor existing={cEdit} onClose={() => setCEdit(null)} />}
    </div>
  );
}

/* ---------- the scope bar: whole group, or one project ---------- */
function ScopeBar() {
  const mob = useIsMobile();
  const { projects, companies, scope, setScope, people } = useProc();
  const active = people.filter(p => p.status === "active");
  const all = scope === "group";
  const cur = projects.find(p => p.id === scope);
  const co = cur && companies.find(c => c.id === cur.company);
  const n = all ? active.length : active.filter(p => p.office === scope).length;
  return (
    <div style={{ marginBottom: 16 }}>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
        <button onClick={() => setScope("group")} style={{ cursor: "pointer", border: `1.5px solid ${all ? C.gold : C.line}`,
          background: all ? C.goldTint : "#fff", color: all ? C.goldDeep : C.inkSoft, borderRadius: 20,
          padding: "8px 15px", font: `600 12px ${sans}`, display: "inline-flex", alignItems: "center", gap: 7 }}>
          <Crown size={14} /> Marbella Group — all
        </button>
        {projects.map(p => {
          const on = scope === p.id;
          return (
            <button key={p.id} onClick={() => setScope(p.id)} style={{ cursor: "pointer", border: `1.5px solid ${on ? C.ink : C.line}`,
              background: on ? C.ink : "#fff", color: on ? "#fff" : C.inkSoft, borderRadius: 20, padding: "8px 14px", font: `600 12px ${sans}` }}>
              {p.short}
            </button>
          );
        })}
      </div>
      <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap", marginTop: 10, font: `12px ${sans}`, color: C.inkSoft }}>
        {all ? (
          <>Every listed project — <b style={{ color: C.ink }}>{projects.length}</b> across <b style={{ color: C.ink }}>{companies.length}</b> companies, <b style={{ color: C.ink }}>{n}</b> people.</>
        ) : cur ? (
          <>
            <span>Employed by <b style={{ color: C.ink }}>{co ? co.name : "—"}</b></span>
            <span style={{ color: C.stone }}>·</span>
            <span style={{ font: `11px ${mono}`, color: C.goldDeep }}>{co && co.gstin ? co.gstin : "no GSTIN"}</span>
            <span style={{ color: C.stone }}>·</span>
            <span style={{ font: `11px ${mono}`, color: cur.reraStatus === "received" ? C.goldDeep : C.amber }}>
              {cur.reraStatus === "received" ? cur.rera : "RERA " + RERA_STATUS[cur.reraStatus].label.toLowerCase()}
            </span>
          </>
        ) : null}
      </div>
    </div>
  );
}

/* ============================== ROSTER AT SCALE · CORRESPONDENCE · JD ==============================
   200 people, a letter desk that knows who it's writing to, and a job-description
   suggester. Everything HR touches is counted so you can see what she actually uses.   */

/* ---------- 200 people, generated but plausible ---------- */
const FIRST_M = ["Amrit","Baldev","Charanjit","Davinder","Gurpreet","Harjeet","Inderjit","Jaswinder","Kuldeep","Lakhvir","Manpreet","Narinder","Onkar","Paramjit","Rajinder","Sukhwinder","Tarlochan","Varinder","Yadwinder","Ashok","Bhupinder","Chetan","Dinesh","Gagandeep","Hardeep","Jagdish","Karan","Mohan","Naveen","Pankaj","Rakesh","Sandeep","Tarun","Vikram","Yogesh","Amit","Bharat","Deepak","Gurmeet","Hemant","Jatinder","Kamal","Mukesh","Nitin","Prem","Ravi","Sunil","Umesh","Vinod","Ramesh"];
const FIRST_F = ["Amandeep","Baljit","Charanjeet","Daljit","Gurmeet","Harpreet","Inderpreet","Jaspreet","Kamaljit","Lakhwinder","Manjit","Navjot","Parminder","Rajwinder","Simran","Sukhjit","Tejinder","Veerpal","Anita","Bhavna","Chetna","Divya","Geeta","Heena","Jyoti","Kavita","Meena","Neha","Pooja","Radha","Sunita","Usha","Vandana","Anjali","Bindu","Deepika","Gurleen","Kiran","Mamta","Nisha","Priya","Ritu","Shalini","Tanvi"];
const SURN = ["Singh","Kaur","Sharma","Verma","Gupta","Chauhan","Yadav","Kumar","Rana","Thakur","Bansal","Goyal","Mehta","Malhotra","Sethi","Nair","Iyer","Bhatia","Sidhu","Gill","Dhillon","Grewal","Sandhu","Brar","Sekhon","Walia","Khanna","Kapoor","Chopra","Arora","Saini","Joshi","Tiwari","Mishra","Pandey","Prasad","Devi","Lal","Ram","Das"];

const ROLES = {
  "Site Engineering": [["Site Engineer",6],["Site Supervisor",8],["Junior Engineer",5],["Surveyor",3],["Project Engineer",3],["Site Manager",2]],
  "Security":         [["Gate Security",14],["Security Supervisor",3],["Club House Guard",6],["Night Guard",5],["Security In-charge",1]],
  "Labour":           [["Bar-bender",8],["Mason",9],["Carpenter",7],["Helper",8],["Painter",4],["Plumber Helper",4],["Electrician Helper",4]],
  "Store":            [["Store Assistant",7],["Store Keeper",4],["Store Supervisor",2],["Material Checker",3]],
  "Purchase":         [["Purchase Assistant",4],["Purchase Executive",3],["Buyer",2]],
  "Accounts":         [["Accounts Assistant",4],["Accountant",3],["Billing Executive",2]],
  "Maintenance":      [["Maintenance Technician",5],["Electrician",4],["Plumber",3],["AC Technician",2],["Lift Technician",1]],
  "QA / QC":          [["QA / QC Engineer",3],["Lab Technician",2],["Quality Inspector",2]],
  "HR":               [["HR Executive",2],["HR Assistant",2],["Payroll Executive",1]],
  "Admin":            [["Club House Manager",2],["Fitness Trainer",3],["House Keeping Supervisor",3],["Receptionist",3],["Front Office Executive",2],["Office Assistant",3],["Driver",4]],
};
const OFFICE_IDS = ["hq","grand","twin","curo","royce"];

function buildRoster() {
  let seed = 20260829;
  const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
  const pick = (a) => a[Math.floor(rnd() * a.length)];
  const M = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  const dstr = (y, m, d) => `${String(d).padStart(2,"0")} ${M[m]} ${y}`;
  const out = []; const used = new Set(); const counters = {};
  Object.entries(ROLES).forEach(([dept, roles]) => {
    roles.forEach(([role, n]) => {
      for (let i = 0; i < n; i++) {
        const female = rnd() > 0.68;
        let name, guard = 0;
        do { name = `${pick(female ? FIRST_F : FIRST_M)} ${pick(SURN)}`; guard++; } while (used.has(name) && guard < 40);
        used.add(name);
        const code = DEPT_CODES[dept] || "GEN";
        counters[code] = (counters[code] || 200) + 1;
        const id = `MB-${code}-${String(counters[code]).padStart(4, "0")}`;
        const jy = 2019 + Math.floor(rnd() * 7), jm = Math.floor(rnd() * 12), jd = 1 + Math.floor(rnd() * 28);
        const by = 1972 + Math.floor(rnd() * 34), bm = Math.floor(rnd() * 12), bd = 1 + Math.floor(rnd() * 28);
        const office = dept === "HR" || dept === "Purchase" || dept === "Accounts"
          ? (rnd() > 0.35 ? "hq" : pick(OFFICE_IDS))
          : pick(OFFICE_IDS.slice(1));
        const employer = office === "curo" || office === "royce" ? "drdc"
          : (dept === "Security" || dept === "Labour") ? "srg" : "dpre";
        const base = { "Site Engineering": 34000, Security: 16000, Labour: 14000, Store: 22000, Purchase: 30000,
          Accounts: 30000, Maintenance: 26000, "QA / QC": 32000, HR: 28000, Admin: 24000 }[dept] || 22000;
        const bump = 1 + Math.floor(rnd() * 5) * 0.12;
        out.push({
          id, name, designation: role, dept, type: dept === "Labour" ? "Labour" : dept === "Security" ? "Security" : "Staff",
          phone: "", email: "", joined: dstr(jy, jm, jd), dob: dstr(by, bm, bd),
          status: "active", perf: 62 + Math.floor(rnd() * 36), growth: "", notes: [],
          office, employer, photo: null,
          _basic: Math.round(base * bump / 1000) * 1000,
          _phone: "9" + String(800000000 + Math.floor(rnd() * 99999999)).slice(0, 9),
        });
      }
    });
  });
  /* --- give the roster a real shape: three ranks, and labour under the site supervisors --- */
  const HEADS = { Purchase: "MB-PUR-0012", Store: "MB-STR-0004", Accounts: "MB-ACC-0002",
    Maintenance: "MB-MNT-0006", HR: "MB-HR-0001", "Site Engineering": "MB-SIT-0021", Admin: "MB-ADM-0001" };
  const rankOf = (d) => {
    const t = d.toLowerCase();
    if (/manager|head|in-charge|incharge/.test(t)) return 3;
    if (/supervisor|senior|project engineer|accountant|store keeper|executive|inspector/.test(t)) return 2;
    if (/engineer|technician|electrician|plumber(?! helper)|surveyor|buyer|receptionist|trainer/.test(t)) return 2;
    return 1;
  };
  out.forEach(p => { p._rank = rankOf(p.designation); });
  const pool = (dept, rank, office) => {
    const same = out.filter(x => x.dept === dept && x._rank === rank && x.office === office);
    return same.length ? same : out.filter(x => x.dept === dept && x._rank === rank);
  };
  out.forEach((p, i) => {
    const head = HEADS[p.dept];
    /* labour is run by whoever supervises that site, not by a labour department */
    if (p.dept === "Labour") {
      const sup = pool("Site Engineering", 2, p.office);
      p.reportsTo = sup.length ? sup[i % sup.length].id : (head || "MB-SIT-0021");
      return;
    }
    if (p._rank === 3) { p.reportsTo = head || "MB-ADM-0001"; return; }
    if (p._rank === 2) {
      const mgr = pool(p.dept, 3, p.office).filter(x => x.id !== p.id);
      p.reportsTo = mgr.length ? mgr[i % mgr.length].id : (head || "MB-ADM-0001");
      return;
    }
    const up = pool(p.dept, 2, p.office).filter(x => x.id !== p.id);
    const up3 = pool(p.dept, 3, p.office).filter(x => x.id !== p.id);
    p.reportsTo = up.length ? up[i % up.length].id : up3.length ? up3[i % up3.length].id : (head || "MB-ADM-0001");
  });
  out.forEach(p => { delete p._rank; });
  return out;
}

/* ---------- email: say WHAT is wrong, not just "invalid" ---------- */
const TYPO_DOMAINS = { "gmial.com":"gmail.com","gmai.com":"gmail.com","gmail.co":"gmail.com","gmail.con":"gmail.com","gnail.com":"gmail.com","yahoo.co":"yahoo.co.in","yahho.com":"yahoo.com","hotmial.com":"hotmail.com","hotmail.co":"hotmail.com","outlok.com":"outlook.com","rediffmail.co":"rediffmail.com","redifmail.com":"rediffmail.com" };
function emailCheck(raw, opts = {}) {
  const v = String(raw || "").trim();
  if (!v) return opts.required ? { level: "error", msg: "No email. Once they leave, the company address dies with the account — this is the only way to reach them." } : { level: "none" };
  if (/\s/.test(v)) return { level: "error", msg: "There's a space in it. Emails can't contain spaces." };
  const at = v.split("@");
  if (at.length === 1) return { level: "error", msg: "No @ sign." };
  if (at.length > 2) return { level: "error", msg: `${at.length - 1} @ signs — there can only be one.` };
  const [local, domain] = at;
  if (!local) return { level: "error", msg: "Nothing before the @." };
  if (!domain) return { level: "error", msg: "Nothing after the @." };
  if (local.length > 64) return { level: "error", msg: "The part before the @ is over 64 characters." };
  if (/^\.|\.$/.test(local)) return { level: "error", msg: "The part before the @ starts or ends with a dot." };
  if (/\.\./.test(v)) return { level: "error", msg: "Two dots in a row." };
  if (!/^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+$/.test(local)) return { level: "error", msg: "Unusual character before the @ — letters, numbers, dot, underscore, hyphen and plus are safe." };
  if (!domain.includes(".")) return { level: "error", msg: `"${domain}" has no dot — a domain needs one, like gmail.com.` };
  if (!/^[A-Za-z0-9.-]+$/.test(domain)) return { level: "error", msg: "Unusual character in the domain." };
  if (/^-|-$/.test(domain.split(".")[0])) return { level: "error", msg: "The domain starts or ends with a hyphen." };
  const tld = domain.split(".").pop();
  if (tld.length < 2) return { level: "error", msg: `".${tld}" is too short to be a real ending.` };
  if (/\d/.test(tld)) return { level: "error", msg: `".${tld}" has digits in it — endings are letters.` };
  const low = domain.toLowerCase();
  if (TYPO_DOMAINS[low]) return { level: "warn", msg: `Did you mean ${local}@${TYPO_DOMAINS[low]}? "${domain}" is a common slip.`, fix: `${local}@${TYPO_DOMAINS[low]}` };
  if (opts.mustBePersonal && COMPANY_DOMAINS.some(d => low === d)) return { level: "error", msg: "That's the company address. This field is their personal one — the company account is closed the day they leave." };
  if (opts.mustBeCompany && !COMPANY_DOMAINS.some(d => low === d)) return { level: "warn", msg: `Not a ${COMPANY_DOMAINS[0]} address. Fine if that's deliberate.` };
  return { level: "ok", msg: `Looks right — ${low}` };
}

